/* ===== crash reporter: shows the real error on-screen so it can be copied ===== */
(function(){
  function showErr(msg){
    let box=document.getElementById('crashBox');
    if(!box){
      box=document.createElement('div'); box.id='crashBox';
      box.style.cssText='position:fixed;left:8px;right:8px;bottom:8px;z-index:99999;'+
        'background:#2a0000;color:#ffb3b3;font:12px/1.4 monospace;padding:10px 12px;'+
        'border:2px solid #ff5b5b;border-radius:8px;white-space:pre-wrap;max-height:40vh;overflow:auto;';
      (document.body||document.documentElement).appendChild(box);
    }
    box.textContent='⚠ CRASH — copy this:\n'+msg;
  }
  window.addEventListener('error',e=>{
    showErr((e.message||'error')+'\n@ '+(e.filename||'')+':'+e.lineno+':'+e.colno+'\n'+((e.error&&e.error.stack)||''));
  });
  window.addEventListener('unhandledrejection',e=>{ showErr('Promise: '+(e.reason&&(e.reason.stack||e.reason.message)||e.reason)); });
})();
/* roundRect polyfill for canvas contexts that lack it */
if(!CanvasRenderingContext2D.prototype.roundRect){
  CanvasRenderingContext2D.prototype.roundRect=function(x,y,w,h,r){
    if(typeof r==="number") r={tl:r,tr:r,br:r,bl:r};
    else if(Array.isArray(r)){ const a=r; r={tl:a[0],tr:a[1]||a[0],br:a[2]||a[0],bl:a[3]||a[1]||a[0]}; }
    this.moveTo(x+r.tl,y);
    this.lineTo(x+w-r.tr,y); this.arcTo(x+w,y,x+w,y+r.tr,r.tr);
    this.lineTo(x+w,y+h-r.br); this.arcTo(x+w,y+h,x+w-r.br,y+h,r.br);
    this.lineTo(x+r.bl,y+h); this.arcTo(x,y+h,x,y+h-r.bl,r.bl);
    this.lineTo(x,y+r.tl); this.arcTo(x,y,x+r.tl,y,r.tl);
    return this;
  };
}
/* =======================================================================
   FOREST BRAWL — arena brawler
   Characters: Nathan (sniper), Daniel (trapper), Yassin (fighter)
   ======================================================================= */
const cv = document.getElementById('game');
const ctx = cv.getContext('2d');
const W = cv.width, H = cv.height;

// Drop a light ambient decor layer (slow-falling leaves) into every menu screen, over the painted scene.
(function decorateScreens(){
  document.querySelectorAll('.screen').forEach(scr=>{
    if(scr.querySelector('.forestDecor')) return;
    const d=document.createElement('div'); d.className='forestDecor';
    let html='';
    // slow-falling leaves scattered across, each with its own speed/offset
    for(let i=0;i<6;i++){ const x=10+i*15, dur=10+i*1.8, delay=-i*2.6, sz=8+(i%3)*3;
      html+=`<div class="leaf" style="left:${x}%; width:${sz}px; height:${sz}px; animation-duration:${dur}s; animation-delay:${delay}s;"></div>`; }
    d.innerHTML=html;
    scr.insertBefore(d, scr.firstChild);
  });
})();

/* =======================================================================
   AUDIO — tiny Web Audio synth (no external files). Lazily created on the
   first user gesture so browsers allow it. sfx(name) plays a short sound.
   ======================================================================= */
let AC=null, masterGain=null, muted=false;
function initAudio(){
  if(AC) return;
  try{
    AC=new (window.AudioContext||window.webkitAudioContext)();
    masterGain=AC.createGain(); masterGain.gain.value=0.35; masterGain.connect(AC.destination);
  }catch(e){ AC=null; }
}
function tone({freq=440,freq2=null,type='sine',dur=0.12,vol=0.5,delay=0}){
  if(!AC||muted) return;
  const t0=AC.currentTime+delay;
  const o=AC.createOscillator(), g=AC.createGain();
  o.type=type; o.frequency.setValueAtTime(freq,t0);
  if(freq2!=null) o.frequency.exponentialRampToValueAtTime(Math.max(1,freq2),t0+dur);
  g.gain.setValueAtTime(0.0001,t0);
  g.gain.exponentialRampToValueAtTime(vol,t0+0.008);
  g.gain.exponentialRampToValueAtTime(0.0001,t0+dur);
  o.connect(g); g.connect(masterGain); o.start(t0); o.stop(t0+dur+0.02);
}
function noise({dur=0.18,vol=0.4,delay=0,lp=1200}){
  if(!AC||muted) return;
  const t0=AC.currentTime+delay;
  const n=Math.floor(AC.sampleRate*dur);
  const buf=AC.createBuffer(1,n,AC.sampleRate); const d=buf.getChannelData(0);
  for(let i=0;i<n;i++) d[i]=(Math.random()*2-1)*(1-i/n);
  const src=AC.createBufferSource(); src.buffer=buf;
  const f=AC.createBiquadFilter(); f.type='lowpass'; f.frequency.value=lp;
  const g=AC.createGain(); g.gain.setValueAtTime(vol,t0); g.gain.exponentialRampToValueAtTime(0.0001,t0+dur);
  src.connect(f); f.connect(g); g.connect(masterGain); src.start(t0); src.stop(t0+dur);
}
function sfx(name){
  if(!AC||muted) return;
  // throttle: at most a handful of sounds per animation frame so audio can never flood
  if(sfx._frame!==frame){ sfx._frame=frame; sfx._count=0; }
  if(++sfx._count>6) return;
  switch(name){
    case 'throw':   tone({freq:520,freq2:280,type:'triangle',dur:0.12,vol:0.4}); break;
    case 'punch':   tone({freq:180,freq2:90,type:'square',dur:0.08,vol:0.5}); noise({dur:0.06,vol:0.25,lp:800}); break;
    case 'catapult':tone({freq:300,freq2:200,type:'sawtooth',dur:0.14,vol:0.35}); break;
    case 'kiss':    tone({freq:660,freq2:990,type:'sine',dur:0.16,vol:0.35}); break;
    case 'dart':    tone({freq:800,freq2:1200,type:'triangle',dur:0.1,vol:0.3}); break;
    case 'hit':     tone({freq:240,freq2:120,type:'square',dur:0.07,vol:0.35}); break;
    case 'explode': noise({dur:0.35,vol:0.6,lp:900}); tone({freq:120,freq2:40,type:'sawtooth',dur:0.3,vol:0.4}); break;
    case 'ko':      tone({freq:300,freq2:60,type:'sawtooth',dur:0.4,vol:0.5}); noise({dur:0.3,vol:0.35,lp:700}); break;
    case 'super':   tone({freq:400,freq2:900,type:'sawtooth',dur:0.25,vol:0.4}); tone({freq:600,freq2:1200,type:'sine',dur:0.3,vol:0.3,delay:0.05}); break;
    case 'heal':    tone({freq:520,freq2:780,type:'sine',dur:0.18,vol:0.3}); break;
    case 'unlock':  [523,659,784,1047].forEach((f,i)=>tone({freq:f,type:'triangle',dur:0.16,vol:0.4,delay:i*0.09})); break;
    case 'ui':      tone({freq:440,freq2:660,type:'square',dur:0.06,vol:0.25}); break;
  }
}
// play a sound only if it happens on/near the visible screen (keeps distant bots quiet)
function nearSfx(name,x,y){ if(typeof onScreen==='function' ? onScreen(x,y,120) : true) sfx(name); }

/* ---------- Background music: a light, tense looping motif (WebAudio, generated) ---------- */
let musicGain=null, musicOn=false, musicTimer=null, musicStep=0, musicNextT=0;
// a brooding A-minor ostinato (bass pulse) + a sparse higher arpeggio that drifts on top
const MUSIC_BASS = [110.00, 110.00, 130.81, 110.00, 98.00, 98.00, 130.81, 146.83]; // A A C A G G C D
const MUSIC_ARP  = [440.00, 523.25, 659.25, 523.25, 493.88, 587.33, 659.25, 880.00];
function ensureMusicGain(){
  if(musicGain||!AC) return;
  musicGain=AC.createGain(); musicGain.gain.value=0.0; musicGain.connect(masterGain);
}
function musicNote(freq,t,dur,vol,type){
  const o=AC.createOscillator(), g=AC.createGain();
  o.type=type; o.frequency.setValueAtTime(freq,t);
  g.gain.setValueAtTime(0.0001,t);
  g.gain.exponentialRampToValueAtTime(vol,t+0.04);
  g.gain.exponentialRampToValueAtTime(0.0001,t+dur);
  o.connect(g); g.connect(musicGain); o.start(t); o.stop(t+dur+0.05);
}
function musicTick(){
  if(!musicOn||!AC){ return; }
  const beat=0.42;                       // seconds per step (~140 half-time, unhurried but tense)
  // schedule any steps whose time has arrived (look ~0.2s ahead)
  while(musicNextT < AC.currentTime+0.2){
    const t=musicNextT, s=musicStep%8;
    // low pulsing bass on every step
    musicNote(MUSIC_BASS[s], t, beat*0.9, 0.16, 'triangle');
    // sparse arpeggio: only on some steps, so it feels tense/uneasy rather than melodic
    if(s===0||s===3||s===5||s===6) musicNote(MUSIC_ARP[s], t+beat*0.15, beat*0.7, 0.055, 'sine');
    // a soft high shimmer at the top of each bar
    if(s===0) musicNote(MUSIC_ARP[s]*2, t+beat*0.3, beat*1.4, 0.02, 'sine');
    musicStep++; musicNextT += beat;
  }
}
function startMusic(){
  if(!AC||muted) return;
  ensureMusicGain(); if(!musicGain) return;
  if(musicOn) return;
  musicOn=true; musicStep=0; musicNextT=AC.currentTime+0.05;
  musicGain.gain.cancelScheduledValues(AC.currentTime);
  musicGain.gain.setValueAtTime(musicGain.gain.value, AC.currentTime);
  musicGain.gain.linearRampToValueAtTime(0.5, AC.currentTime+1.2);   // fade in
  clearInterval(musicTimer); musicTimer=setInterval(musicTick, 60);
}
function stopMusic(){
  musicOn=false; clearInterval(musicTimer); musicTimer=null;
  if(musicGain&&AC){ musicGain.gain.cancelScheduledValues(AC.currentTime);
    musicGain.gain.setValueAtTime(musicGain.gain.value, AC.currentTime);
    musicGain.gain.linearRampToValueAtTime(0.0, AC.currentTime+0.6); }
}

