const ALL_COSMETIC_IDS = Object.keys(COSMETICS).filter(id=>!COSMETICS[id].archived);   // archived skins are kept in COSMETICS but excluded everywhere (hidden vault)
const RARITY_COLOR = {common:'#8fd3a8', rare:'#f4c430', silver:'#dfe6ef', mythic:'#c77dff', special:'#ff9838'};
// archetype sort rank: Common < Rare (rare+silver share the "recolor+gear" band) < Special (mythic + toybox packs)
const RARITY_RANK = {common:0, rare:1, silver:1, mythic:2, special:2};
const rarityRank = id => RARITY_RANK[(COSMETICS[id]||{}).rarity] ?? 0;
// short marker per rarity for chips/lists
const rarityStar = r => (r==='mythic'||r==='special')?'✦ ':r==='rare'?'★ ':r==='silver'?'❖ ':'';

