const SAVE_KEY='forestbrawl_save_v4';

// ---- GROWTH: per-brawler prestige. Wins mainly, plus a tiny bit per KO. 5 forest tiers. ----
const GROWTH_TIERS = [
  {name:'Seedling', at:0,    color:'#8fd3a8', icon:'🌱'},
  {name:'Sprout',   at:120,  color:'#6fae4f', icon:'🌿'},
  {name:'Sapling',  at:320,  color:'#3f7d3a', icon:'🍃'},
  {name:'Grove',    at:640,  color:'#e0a800', icon:'🌳'},
  {name:'Canopy',   at:1100, color:'#f4c430', icon:'🌲'}
];
const GROWTH_WIN=10, GROWTH_KO=0.5;   // GROWTH_WIN kept for compat; placement table drives wins now
// Each Growth tier you reach (Sprout+) drops loot for that brawler AND unlocks the next lore fragment.
// Reward per tier index (1=Sprout .. 4=Canopy). tokens + a chance at that brawler's own skin/emote.
const GROWTH_REWARD = [
  null,                                   // Seedling (index 0) — no reward, just the starting lore
  {tokens:2},                             // Sprout
  {tokens:3, chance:{emote:0.5}},         // Sapling
  {tokens:4, chance:{skin:0.5}},          // Grove
  {tokens:6, chance:{skin:0.6, emote:0.5}}// Canopy
];
// Lore fragments — index 0 shows at Seedling (free); 1..4 unlock as you reach Sprout/Sapling/Grove/Canopy.
// The web of relationships is drawn from the brawlers' shared backstory.
const GROWTH_LORE = {
  nathan:  ["A small-town pitcher with a cannon for an arm.","Scouts called him 'the kid who throws smoke.'","He turned down the majors — said the forest needed a closer.","Practices alone at dawn, hurling stones across the ravine.","They say his fastball once knocked a bird clean out of the sky. He still feels bad about it."],
  daniel:  ["A tinkerer who loves things that go BOOM.","He builds his bombs from scrap he finds in the woods.","Nathan's old bullpen buddy — they still argue about curveballs.","Every explosion, he counts the seconds like a nervous habit. Tick. Tock.","His workshop has one rule taped to the door: 'If it ticks, RUN.'"],
  yassin:  ["A street-trained brawler with fists like hammers.","He learned to fight protecting his little corner of the woods.","Trains against Fionn — the only one who can take his combos.","No weapons, no tricks. Just hands and stubbornness.","He's never lost a fistfight. He's also never admitted losing one."],
  josh:    ["A kid who'd rather build than break.","He hauls logs twice his size and never complains.","Renas is his little brother — Josh taught him everything.","Every hut he builds, he carves a tiny 'J' into the corner.","He dreams of building a treehouse so tall it touches the canopy. Renas is already scared of the ladder."],
  lars:    ["A soft-hearted teen who fights with kindness.","His blown kisses actually patch up scrapes and bruises.","Everyone underestimates the boy in the pink hoodie.","He can't stand to see anyone hurt — even the ones he's fighting.",":3 — the face he makes right before he wins."],
  milo:    ["A speedy scout who sees the shot before it's there.","Fastest feet in the forest, quickest eye on the trigger.","Johan is his father — the tall, quiet cleaner.","He races his own shadow at sunset and usually wins.","Milo left home young to prove himself. Johan mops the same spot every night, waiting for him to visit."],
  deniz:   ["A Turkish bruiser who carries winter with him.","Frost curls off his knuckles even in summer.","He speaks little and freezes fast.","The cold never bothered him — it's the only thing that kept him company.","Legend says he once froze a whole lake to cross it. He just wanted to skip the ferry fare."],
  fionn:   ["A swordsman cursed with a head shaped like an egg.","He's made peace with the jokes. Mostly.","Yassin's sparring partner — fists versus steel.","When he calls his banshee, the whole forest goes quiet.","He wears the egg jokes like armor. Underneath, he's the loneliest knight in the woods."],
  reshman: ["A street-food cook whose spices can heal or hurt.","One taste of his broth and your wounds close up.","His cart is always parked where a fight's about to start.","He feeds friend and foe alike — a warm meal knows no sides.","He learned every recipe from his grandmother, who told him: 'Feed them first. Fight them never.'"],
  renas:   ["Josh's little brother, quick with a boomerang.","He follows Josh everywhere, mimicking his every move.","He can't build like Josh yet — so he throws instead.","His boomerang always comes back. So does he.","One day he'll be bigger than Josh. He reminds him of this daily."],
  adam:    ["A table-tennis prodigy with a killer serve.","Born a twin — sort of. It's complicated.","His mother was a surrogate for another... thing.","Every serve is a memory of the brother he can't forgive.","Adam and Evil Adam shared a womb, not a bond. He's spent his life trying to serve past that."],
  evadam:  ["A creature of the night with a taste for blood.","Not Adam's brother — his womb-mate. There's a difference.","The Serveerster is the only one he'd never bite.","He and Adam are sworn enemies, bound by the same beginning.","He loves the Serveerster fiercely. It terrifies him — monsters aren't supposed to love."],
  otis:    ["A space-suited beagle who bounces off the moon.","Loyal to a fault, brave past all reason.","Dean is his owner — the two are never far apart.","He guards Dean's camp every night, one ear always up.","Otis followed Dean into the woods and never looked back. A dog picks his human once, for life."],
  johan:   ["An impossibly tall janitor who fights with a mop.","He keeps the whole forest spotless, silently.","Milo is his son — his pride, his worry, his whole world.","He leaves the porch light on every single night.","Johan never says much. But every clean floor is a message: 'Come home safe, Milo.'"],
  robin:   ["A chubby kid whose tears are surprisingly weaponized.","He cries when he's sad, scared, or winning.","The other kids don't get it — the tears just... work.","Behind the sobs is a fighter who never quits.","'Cry me a river,' they laugh. So he does. And then he floods them."],
  jake:    ["A hunter blessed by Artemis herself.","The moon guides every arrow he looses.","He never misses when the moonlight touches his bow.","At the new moon, he hunts blind — and trusts the goddess.","Artemis chose him for his patience. He waits for the perfect shot the way others wait for spring."],
  kimchi:  ["A trapper who ferments chaos in ceramic jars.","Her kimchi bombs sear anyone who steps in the puddle.","She insists everything tastes better spicy — even combat.","Her jars have been fermenting since before the woods had a name.","'Too spicy to handle,' she warns. Nobody ever listens. Everybody regrets it."],
  dean:    ["A frontier gunslinger with a bounty book.","He marks his targets and always collects.","Otis is his dog — his partner, his family.","He's chased outlaws across three forests and one desert.","Dean talks to Otis more than to people. Otis is a better listener, and he never asks for a cut."],
  claire:  ["A scout whose fury is her fuel.","The angrier she gets, the harder she hits.","Ragebait is a strategy, not an accident.","When her rage meter fills, the forest learns to duck.","She's not always angry. She just fights better when she is. Convenient, that."],
  waitress:["A restaurant server who heals with a full menu.","Knife in one hand, fork in the other — dinner is served.","She's Evil Adam's girlfriend. Yes, the vampire.","During Dinner Rush, nobody in her section goes hungry — or unhealed.","She knows what he is. She loves him anyway. 'Everyone deserves a warm meal,' she says — even the undead."],
  sanne:   ["A sailor who trap-fights with a ship's anchor.","She hurls it, plants it, and reels foes in.","The sea's gone, but the anchor stayed with her.","She names every anchor. The current one is 'Beatrice.'","Sanne washed ashore here years ago. She keeps the anchor in case the sea ever comes back for her."],
  fluharty:["A baseball pitcher with an unhittable curve.","His ball bends where no ball should.","Coaches called it witchcraft. He calls it practice.","Strike three, every time — if you can even see it coming.","He throws for hours after everyone's gone home. The curve isn't a gift. It's ten thousand lonely pitches."],
  stalker: ["A hooded figure who's always... watching.","Nobody's seen his full face. One glowing eye is all you get.","He sees you long before you see him.","His cameras never blink. Neither, they say, does he.","No one knows where Stalker came from. He knows exactly where you are, though. He always does."],
  marlin:  ["A sun-soaked sniper who drifted in from the Miami coast.","He fights barefoot when he can. Sand between the toes.","His sun-shots leave the ground warm long after they pass.","He met a siren named Maria off the reef — her song, and he never left.","Maria Miami taught him the siren's wave on their wedding night. When he calls it, for a moment the sea — and her voice — are with him."],
  sonia:   ["The crown princess of the small European kingdom of Novoselic.","Impeccably polite — and endlessly, cheerfully fascinated by the macabre.","She trained with Novoselic's royal guard; the spear is second nature.","Her people adore her; she'd lay down her life for any of them.","Far from home, she rallies these brawlers like her own subjects. A princess protects her people — even the strange ones."],
  jax:     ["A one-man comment section who fights with pure snark.","Every insult he throws lands like a brick — because it kind of is one.","He never blocks; he just ratios you into next week.","Nobody knows his real name. Everyone knows his roasts.","He types faster than most people think. Unfortunately for you, he also aims."],
  kapper:  ["A barber who never stopped mid-cut, even when the fighting started.","Two blades, zero patience for a bad fade.","He insists everyone looks better after he's done with them.","His chair is always open. Sitting down is the risky part.","'A little off the top,' he says, already dashing. It is never a little."],
  dynant:  ["A firefighter who wandered into the woods chasing a wildfire and stayed.","He treats every brawl like a blaze to be contained.","The hose never leaves his hands; neither does the calm.","He'll douse a burning ally without being asked — even a rival, sometimes.","'Stand back,' he says, already spraying. Everyone stands back."],
  adma:    ["A field medic with the poise of someone who's never once panicked.","She reads a fight like a chart — and always knows who's about to fall.","'Hit me,' she says, smiling. People really shouldn't.","Every scar she carries paid for someone else's recovery.","She turns the damage she soaks into the strength to keep standing. Ten out of ten, and she knows it."],
  kayo:    ["Two cats, one fight. Kayo takes the hits; Yara takes the openings.","Kayo is all shoulders and bad temper — he wades in and refuses to move.","Yara is a blur of teal and claws, gone before you finish swinging.","They tag in and out mid-brawl like they share a single heartbeat.","Nobody's sure if they're brothers, rivals, or the same cat wearing two moods. They're not telling."]
};
function growthTier(pts){ let t=GROWTH_TIERS[0]; for(const g of GROWTH_TIERS) if(pts>=g.at) t=g; return t; }
function growthOf(cid){ return (save.growth&&save.growth[cid])||0; }
// ---- Evil Jax roast lines: short gamer-snark for attack bubbles; Rose-Wilson weight for super/KO/taunt ----
const JAX_SHOTS = ["cope","skill issue","ratio","L + ratio","stay mad","mid.","sit down","get good","yikes","touch grass","who asked?","nice try","k.","and? 🙄","cry about it"];
const JAX_SUPER_LINES = ["this is where you stop.","all of you. down.","know your place.","lesson's over.","CONVERSATION OVER."];
const JAX_KO_LINES = ["predictable.","and that's that.","you were never a threat.","next.","don't get up.","blocked. 🚫","deleted. 🗑️"];
// Skin-emote effect proc: if Jax has one of his special skin-emotes equipped, his roast has a slightly
// boosted chance to carry that skin's bonus effect. Returns null or {kind:'slow'|'burn'|'knock'}.
function jaxRoastEffect(f){
  const eff = f.jaxEmoteFx; if(!eff) return null;   // set on the fighter when a Jax skin-emote is equipped
  const chance = 0.32;   // a bit higher than a plain roast so the special reads as "special"
  return (Math.random()<chance) ? {kind:eff} : null;
}
// which bonus effect Jax's currently-equipped emote grants (only skin-emotes carry an `fx`); null if none
function jaxEquippedEmoteFx(){
  const eq = save.equippedEmote && save.equippedEmote['jax'];
  const em = eq && EMOTES[eq];
  return (em && em.fx) ? em.fx : null;
}
