const QUEST_BY_ID = Object.fromEntries(QUEST_POOL.map(q=>[q.id,q]));
// the mega-quest: unlocked every 10 completed quests, must be finished to earn the Mythic Masters pack.
// it lives outside the weighted pool (never rolls randomly) and doesn't count toward the next mega.
// The GOAL rotates: each time a mega slot is created we pick a fresh variant so it isn't always "win 10".
const MEGA_VARIANTS = [
  {text:'MEGA-QUEST: Win 10 matches',              goal:10,     metric:'win'},
  {text:'MEGA-QUEST: Knock out 120 enemies',        goal:120,    metric:'ko'},
  {text:'MEGA-QUEST: Deal 80,000 damage',           goal:80000,  metric:'dmg'},
  {text:'MEGA-QUEST: Play 20 matches',              goal:20,     metric:'match'},
  {text:'MEGA-QUEST: Clear 15 Silverdome rounds',   goal:15,     metric:'arena'},
  {text:'MEGA-QUEST: Win 6 team-mode matches',      goal:6,      metric:'win', mode:'relay'}
];
const MEGA_QUEST = {id:'mega_mythic', text:'MEGA-QUEST: Win 10 matches for a Mythic Masters pack', goal:10, metric:'win', diff:'mega', mega:true, reward:{pack:'mythic_masters'}};
QUEST_BY_ID[MEGA_QUEST.id]=MEGA_QUEST;
// pick a fresh mega goal and write it onto the shared MEGA_QUEST (only one mega is ever active at a time).
function rollMegaQuest(){
  const v=MEGA_VARIANTS[Math.floor(Math.random()*MEGA_VARIANTS.length)];
  MEGA_QUEST.text=v.text+' for a Mythic Masters pack'; MEGA_QUEST.goal=v.goal; MEGA_QUEST.metric=v.metric;
  if(v.mode) MEGA_QUEST.mode=v.mode; else delete MEGA_QUEST.mode;
  QUEST_BY_ID[MEGA_QUEST.id]=MEGA_QUEST;
}

const ALL_CHAR_IDS = Object.keys(CHARS).filter(k=>k!=='dummy' && k!=='spore');   // 'dummy' (training) + 'spore' (Binas minion) are special — never in rosters, Trophy Road, or the gallery
let save={points:0, lifetimePoints:0, unlocked:STARTER_CHARS.slice(), cosmetics:[], emotes:[], equipped:{}, equippedEmote:{}, cosmeticsClaimed:0, questsDone:0, skinPoints:0, tokens:0, pearls:0, upgrades:{}, arenaBest:0, totalArenaWins:0, growth:{}, growthClaimed:{}, quests:[], doublers:{trophy:0,ko:0}, stats:{matches:0,wins:0,kos:0,deaths:0,byChar:{}}, touchMode:null};
// pick `n` fresh quest ids not already active
// how likely each difficulty is to roll — easy common, hard rare
const QUEST_WEIGHT = { easy:6, med:3, hard:1 };
function rollQuests(n){
  const active=new Set((save.quests||[]).map(q=>q.id));
  let pool=QUEST_POOL.filter(q=>!active.has(q.id));
  const picks=[];
  // weighted pick without replacement: rarer difficulties are much less likely
  for(let k=0; k<n && pool.length; k++){
    let total=0; pool.forEach(q=>total+=(QUEST_WEIGHT[q.diff]||1));
    let r=Math.random()*total, idx=0;
    for(let i=0;i<pool.length;i++){ r-=(QUEST_WEIGHT[pool[i].diff]||1); if(r<=0){ idx=i; break; } }
    picks.push(pool[idx]);
    pool=pool.filter((_,i)=>i!==idx);
  }
  return picks.map(q=>({id:q.id, prog:0, done:false}));
}
function ensureQuests(){ if(!Array.isArray(save.quests)) save.quests=[]; while(save.quests.filter(q=>!QUEST_BY_ID[q.id]||!QUEST_BY_ID[q.id].mega).length<3){ const add=rollQuests(1); if(!add.length) break; save.quests.push(add[0]); } }
function loadSave(){
  try{ const s=JSON.parse(localStorage.getItem(SAVE_KEY)); if(s&&Array.isArray(s.unlocked)){ save=s; } }catch(e){}
  // fill any missing fields for older saves
  if(!Array.isArray(save.cosmetics)) save.cosmetics=[];
  if(!Array.isArray(save.emotes)) save.emotes=[];             // owned emotes/taunts
  if(typeof save.tokens!=='number') save.tokens=0;            // Silver Tokens (Silverdome Arena)
  if(typeof save.pearls!=='number') save.pearls=0;            // Pearls (Siren Sanctuary currency, from quests)
  if(typeof save.tickets!=='number') save.tickets=0;          // Prize Tickets (Payload Panic currency → Toybox toy skins)
  if(typeof save.acorns!=='number') save.acorns=0;            // Acorns (Nature pack currency → nature skins)
  if(typeof save.stardust!=='number') save.stardust=0;        // Stardust (Alien Whiteout currency → Space skins @ The Observatory)
  if(typeof save.atoms!=='number') save.atoms=0;              // Atoms (Binas Boss currency → Laboratory skins)
  if(typeof save.upgrades!=='object'||!save.upgrades) save.upgrades={};   // per-brawler Sanctuary upgrade owned
  if(typeof save.arenaBest!=='number') save.arenaBest=0;      // best Silverdome round reached
  if(typeof save.totalArenaWins!=='number') save.totalArenaWins=0;  // lifetime rounds won (drives shop rotation)
  if(typeof save.growth!=='object'||!save.growth) save.growth={};   // per-brawler Growth points
  if(typeof save.growthClaimed!=='object'||!save.growthClaimed) save.growthClaimed={};   // tiers whose loot was granted
  if(typeof save.silverdomeDone!=='object'||!save.silverdomeDone) save.silverdomeDone={};   // per-brawler: cleared all Silverdome rounds
  // backfill: any tier a brawler has ALREADY reached is treated as claimed (no retroactive loot flood)
  Object.keys(save.growth).forEach(cid=>{
    const reached=GROWTH_TIERS.indexOf(growthTier(save.growth[cid]||0));
    const arr = save.growthClaimed[cid] || (save.growthClaimed[cid]=[]);
    for(let t=1; t<=reached; t++){ if(!arr.includes(t)) arr.push(t); }
  });
  if(!Array.isArray(save.quests)) save.quests=[];                   // active rolling quests
  if(typeof save.doublers!=='object'||!save.doublers) save.doublers={trophy:0,ko:0};  // pending reward doublers
  if(typeof save.equipped!=='object'||!save.equipped) save.equipped={};
  // if a brawler is wearing a now-archived skin, drop back to default so archived skins never show in-game
  Object.keys(save.equipped).forEach(cid=>{ const eq=save.equipped[cid]; if(eq && COSMETICS[eq] && COSMETICS[eq].archived) save.equipped[cid]=null; });
  if(typeof save.equippedEmote!=='object'||!save.equippedEmote) save.equippedEmote={};  // per-brawler chosen emote
  if(typeof save.cosmeticsClaimed!=='number') save.cosmeticsClaimed=0;
  if(typeof save.questsDone!=='number') save.questsDone=0;   // lifetime completed quests (drives the mega-quest pack)
  if(typeof save.stats!=='object'||!save.stats) save.stats={matches:0, wins:0, kos:0, deaths:0, byChar:{}};  // lifetime play stats
  if(typeof save.stats.byChar!=='object'||!save.stats.byChar) save.stats.byChar={};
  if(typeof save.skinPoints!=='number') save.skinPoints=0;   // KO-earned currency for skins (separate from Trophy Road)
  if(save.touchMode===undefined) save.touchMode=null;        // null = auto-detect touch; true/false = manual override
  // migrate old cumulative-threshold saves: 'points' used to be a running total (which would
  // instant-buy everything under the new spend model). Convert it to a lifetime stat and reset
  // the spendable balance to 0, so you keep unlocked brawlers but no leftover free credit.
  if(typeof save.lifetimePoints!=='number'){ save.lifetimePoints=save.points||0; save.points=0; }
  // starters are always owned; the rest are earned on the Trophy Road
  STARTER_CHARS.forEach(c=>{ if(!save.unlocked.includes(c)) save.unlocked.push(c); });
  // repair an over-inflated balance from older builds: cap it so a giant surplus can't
  // instantly buy a brawler added in a future update (all owned -> 0; else < next cost)
  const nb=nextBrawlerNode();
  save.points = nb ? Math.min(save.points, nb.cost-1) : 0;
  ensureQuests();   // always have 3 active quests
}
// is touch mode effectively on? (manual override wins; otherwise auto-detect a touch device)
const DEVICE_HAS_TOUCH = ('ontouchstart' in window) || (navigator.maxTouchPoints>0);
function touchActive(){ return save.touchMode===null ? DEVICE_HAS_TOUCH : !!save.touchMode; }
function persistSave(){ try{ localStorage.setItem(SAVE_KEY,JSON.stringify(save)); }catch(e){} }
function isUnlocked(id){ return save.unlocked.includes(id); }
function allCharsUnlocked(){ return TROPHY_ROAD.filter(n=>n.type==='char').every(n=>isUnlocked(n.id)); }
function ownsCosmetic(id){ return save.cosmetics.includes(id); }
// full-size skin preview overlay (the "i" button on shop/sanctuary skin cards)
function openSkinPeek(id){
  const co=COSMETICS[id]; if(!co) return;
  const tier = co.rarity==='special'?('✦ SPECIAL · '+(co.pack==='nature'?'NATURE':co.pack==='space'?'SPACE':'PLAYTIME')+' ✦') : co.rarity==='mythic'?'✦ SPECIAL · MYTHIC ✦' : co.rarity==='silver'?'❖ SILVERDOME SKIN ❖' : co.rarity==='rare'?'★ RARE SKIN ★' : 'COMMON SKIN';
  document.getElementById('skinPeekTier').textContent=tier;
  document.getElementById('skinPeekName').textContent=co.name;
  document.getElementById('skinPeekChar').textContent='for '+CHARS[co.char].name;
  // note any skin-locked emote that comes with this skin
  const em=Object.values(EMOTES).find(e=>e.skinLocked===id);
  const emBox=document.getElementById('skinPeekEmote');
  emBox.textContent = em ? `💬 Exclusive emote: “${em.text}”` : '';
  try{ drawPortrait(document.getElementById('skinPeekArt'), co.char, id); }catch(e){}
  document.getElementById('skinPeek').classList.remove('hidden');
  sfx('ui');
}
document.getElementById('skinPeekClose').onclick=()=>{ document.getElementById('skinPeek').classList.add('hidden'); sfx('ui'); };
document.getElementById('skinPeek').onclick=(ev)=>{ if(ev.target.id==='skinPeek') document.getElementById('skinPeek').classList.add('hidden'); };
// a character still has a skin to earn if you don't own both its common and rare yet
function charsWithSkinsLeft(){
  return TROPHY_ROAD.filter(n=>n.type==='char' && isUnlocked(n.id)).map(n=>n.id)
    .filter(cid => ALL_COSMETIC_IDS.some(sid => COSMETICS[sid].char===cid && !ownsCosmetic(sid)));
}
// within a character, you earn the common first, then the rare
function nextSkinForChar(cid){
  const common = ALL_COSMETIC_IDS.find(sid=>COSMETICS[sid].char===cid && COSMETICS[sid].rarity==='common');
  if(common && !ownsCosmetic(common)) return common;   // common must come first
  // then hand out rares in table order (a brawler can have several)
  const rares = ALL_COSMETIC_IDS.filter(sid=>COSMETICS[sid].char===cid && COSMETICS[sid].rarity==='rare');
  for(const r of rares){ if(!ownsCosmetic(r)) return r; }
  return null;
}
// any KO-cycle skins still obtainable (excludes shop-only Silverdome + pack-only mythic/special skins)
function availableCosmetics(){ return ALL_COSMETIC_IDS.filter(id=>!ownsCosmetic(id) && !COSMETICS[id].shopOnly && !COSMETICS[id].mythicOnly && !COSMETICS[id].special && isUnlocked(COSMETICS[id].char)); }
// --- emotes: now SHOP-ONLY (bought with Silver Tokens), no longer in the KO cycle ---
function ownsEmote(id){ return save.emotes.includes(id); }
// combined pool of everything the KO cycle can still roll (skins only now — emotes moved to the shop)
function availableUnlockables(){
  // KO-points can earn both skins AND emotes — so the cycle lasts far longer than skins alone.
  // (Skin-locked emotes are excluded: those only come with their mythic skin.)
  const skins = availableCosmetics().map(id=>({kind:'skin',id}));
  const emotes = ALL_EMOTE_IDS.filter(id=>!ownsEmote(id) && !EMOTES[id].skinLocked && isUnlocked(EMOTES[id].char)).map(id=>({kind:'emote',id}));
  return skins.concat(emotes);
}
// emotes you own for a given brawler, in table order.
// A skin-locked emote is available only while its mythic skin is the equipped cosmetic (never "owned" otherwise).
function emotesForChar(cid){
  return ALL_EMOTE_IDS.filter(id=>{
    const em=EMOTES[id]; if(em.char!==cid) return false;
    if(em.skinLocked) return save.equipped && save.equipped[cid]===em.skinLocked;
    return ownsEmote(id);
  });
}
// start the emote cycle on the player's equipped emote for this brawler (0 if none/unowned)
function emoteStartIdx(cid){ const owned=emotesForChar(cid), eq=save.equippedEmote&&save.equippedEmote[cid]; const i=owned.indexOf(eq); return i>=0?i:0; }
// cost of the next skin in KO-points: 500 while brawlers remain locked, 300 once all are unlocked
function skinCost(){ return allCharsUnlocked() ? SKIN_STEP_FULL : SKIN_STEP_PRE; }
// KO-points still needed for the next skin
function skinPtsToNext(){ return Math.max(0, skinCost()-save.skinPoints); }

// growth points earned for a finishing rank (1st..5th). Bad placements COST points. Relay/arena win = rank 1.
const GROWTH_PLACEMENT = {1:10, 2:5, 3:2, 4:-1, 5:-3};
// ---- Growth: add prestige points to a brawler (never below 0); returns the tier name if it ranked up, else null ----
function awardGrowth(cid, placementPts, kos){
  if(!cid) return null;
  const beforeIdx = GROWTH_TIERS.indexOf(growthTier(growthOf(cid)));
  save.growth[cid]=Math.max(0, (save.growth[cid]||0) + placementPts + kos*GROWTH_KO);
  const afterIdx = GROWTH_TIERS.indexOf(growthTier(growthOf(cid)));
  if(afterIdx<=beforeIdx) return null;   // no upward tier crossing
  // claim every newly-crossed tier that hasn't been rewarded yet (can't be re-farmed by bouncing)
  if(!save.growthClaimed) save.growthClaimed={};
  const claimed = save.growthClaimed[cid] || (save.growthClaimed[cid]=[]);
  const parts=[];
  for(let t=beforeIdx+1; t<=afterIdx; t++){
    if(claimed.includes(t)) continue;
    claimed.push(t);
    const rw=GROWTH_REWARD[t]; if(rw) grantGrowthLoot(cid, rw, parts);
  }
  const tierName = GROWTH_TIERS[afterIdx].name;
  return { tier: tierName, loot: parts };   // richer result: new tier name + any loot lines
}
// hand out a Growth-tier reward, biased toward THIS brawler's own skin/emote
function grantGrowthLoot(cid, rw, parts){
  if(rw.tokens){ save.tokens+=rw.tokens; parts.push(`🎟${rw.tokens}`); }
  if(rw.chance){
    if(rw.chance.emote!==undefined && Math.random()<rw.chance.emote){
      // prefer an unowned emote for this brawler, else any unowned
      let pool=ALL_EMOTE_IDS.filter(id=>EMOTES[id].char===cid && !ownsEmote(id) && !EMOTES[id].skinLocked);
      if(!pool.length) pool=ALL_EMOTE_IDS.filter(id=>!ownsEmote(id) && !EMOTES[id].skinLocked);
      if(pool.length){ const id=pool[Math.floor(Math.random()*pool.length)]; save.emotes.push(id); parts.push(`💬 ${EMOTES[id].name}`); }
    }
    if(rw.chance.skin!==undefined && Math.random()<rw.chance.skin){
      let pool=ALL_COSMETIC_IDS.filter(id=>COSMETICS[id].char===cid && !ownsCosmetic(id) && !COSMETICS[id].shopOnly && !COSMETICS[id].mythicOnly);
      if(!pool.length) pool=ALL_COSMETIC_IDS.filter(id=>!ownsCosmetic(id) && !COSMETICS[id].shopOnly && !COSMETICS[id].mythicOnly);
      if(pool.length){ const id=pool[Math.floor(Math.random()*pool.length)]; save.cosmetics.push(id); if(!save.equipped[COSMETICS[id].char]) save.equipped[COSMETICS[id].char]=id; parts.push(`🎨 ${COSMETICS[id].name}`); growthSkinReveals.push(id); }   // queue it for the card-flip reveal
    }
  }
}
// ---- Quests: advance any active quest matching this metric; returns [{quest, reward}] just completed ----
// ctx: {char, role, won, mode}
function questAdvance(metric, amount, ctx){
  ensureQuests(); const done=[];
  save.quests.forEach(slot=>{
    if(slot.done) return;
    const q=QUEST_BY_ID[slot.id]; if(!q || q.metric!==metric) return;
    if(q.role && (!ctx || CHARS[ctx.char]?.role!==q.role)) return;   // role-gated quests
    if(q.mode && (!ctx || ctx.mode!==q.mode)) return;                // mode-gated quests (play/win/ko in a specific mode) (Fighter/Sniper/Trapper/Healer)
    if(q.mode && (!ctx || ctx.mode!==q.mode)) return;                // mode-gated quests (ffa/relay/pearl/payload/ctf/whiteout)
    slot.prog=Math.min(q.goal, slot.prog+amount);
    if(slot.prog>=q.goal){ slot.done=true; done.push(q); }
  });
  return done;
}
// grant a completed quest's reward; returns a short label describing what was granted
function grantQuestReward(q){  const r=q.reward, parts=[];
  if(r.pack){
    // rotate across every collectible pack that still has unowned skins: Mythic Masters, Playtime (Toybox), Nature (Grove), Space (Observatory)
    const eligible=[];
    if(MYTHIC_IDS.some(id=>!ownsCosmetic(id))) eligible.push('mythic_masters');
    if(PLAYTIME_IDS.some(id=>!ownsCosmetic(id))) eligible.push('playtime');
    if(NATURE_IDS.some(id=>!ownsCosmetic(id))) eligible.push('nature');
    if(SPACE_IDS.some(id=>!ownsCosmetic(id))) eligible.push('space');
    const pack = eligible.length ? eligible[Math.floor(Math.random()*eligible.length)] : 'mythic_masters';   // all owned → converts to Pearls in the roulette
    pendingPacks.push(pack);
    parts.push(pack==='playtime' ? "✦ Playtime pack" : pack==='nature' ? "✦ Nature pack" : pack==='space' ? "✦ Space pack" : "✦ Mythic Masters pack"); return parts.join(" · ");
  }
  if(r.tokens){ save.tokens+=r.tokens; parts.push(`🎟${r.tokens}`); }
  if(r.pearls){ save.pearls+=r.pearls; parts.push(`🫧${r.pearls}`); }
  if(r.doubler==='trophy'){ save.doublers.trophy=(save.doublers.trophy||0)+1; parts.push("Trophy Doubler"); }
  if(r.doubler==='ko'){ save.doublers.ko=(save.doublers.ko||0)+1; parts.push("KO Doubler"); }
  if(r.chance){
    if(r.chance.emote!==undefined && Math.random()<r.chance.emote){ const pool=ALL_EMOTE_IDS.filter(id=>!ownsEmote(id) && !EMOTES[id].skinLocked); if(pool.length){ const id=pool[Math.floor(Math.random()*pool.length)]; save.emotes.push(id); parts.push(`💬 ${EMOTES[id].name}`); } }
    if(r.chance.skin!==undefined && Math.random()<r.chance.skin){ const pool=ALL_COSMETIC_IDS.filter(id=>!ownsCosmetic(id) && !COSMETICS[id].shopOnly && !COSMETICS[id].mythicOnly); if(pool.length){ const id=pool[Math.floor(Math.random()*pool.length)]; save.cosmetics.push(id); if(!save.equipped[COSMETICS[id].char]) save.equipped[COSMETICS[id].char]=id; parts.push(`🎨 ${COSMETICS[id].name}`); } }
  }
  return parts.join(" · ");
}
// count completed NORMAL quests toward the mega-quest; every 10th unlocks the mega-quest slot (which must
// then be completed to earn the pack). Returns true if a new mega-quest was just unlocked.
function creditQuestsDone(n){
  if(!n) return false;
  const before=save.questsDone||0, after=before+n;
  save.questsDone=after;
  const crossed = Math.floor(after/10) > Math.floor(before/10);
  if(crossed && !save.quests.some(s=>s.id===MEGA_QUEST.id)){
    rollMegaQuest();   // pick a fresh mega goal so it isn't always "Win 10"
    save.quests.push({id:MEGA_QUEST.id, prog:0, done:false});   // add the special mega-quest slot
    return true;
  }
  return false;
}
// called once per finished match: award Growth to the played brawler + advance quests.
// `rank` = finishing place (1=win). returns HTML lines for the reward panel.
function trackMatchResult(rank){
  const lines=[];
  const cid=chosen;
  const won = rank===1;
  // --- lifetime play stats ---
  const st=save.stats; st.matches++; st.kos+=defeated; if(won)st.wins++; else st.deaths++;
  const bc=st.byChar[cid]||(st.byChar[cid]={matches:0,wins:0,kos:0});
  bc.matches++; bc.kos+=defeated; if(won)bc.wins++;
  const up=awardGrowth(cid, GROWTH_PLACEMENT[rank]||1, defeated);
  if(up){ const lootTxt = up.loot&&up.loot.length ? ` — ${up.loot.join(' ')}` : '';
    lines.push(`<span style="color:#8fd3a8;font-weight:bold;">🌿 ${CHARS[cid].name} grew to ${up.tier}!${lootTxt}</span>`); }
  // advance quests: match played, win, KOs, damage dealt, and mode-specific goals
  const completed=[];
  const qc={char:cid, mode:gameMode};   // ctx carries the played character (for role gating) + the mode
  questAdvance('match',1,qc).forEach(q=>completed.push(q));
  if(won) questAdvance('win',1,qc).forEach(q=>completed.push(q));
  if(defeated>0) questAdvance('ko',defeated,qc).forEach(q=>completed.push(q));
  if(matchDamage>0) questAdvance('dmg',Math.round(matchDamage),qc).forEach(q=>completed.push(q));
  completed.forEach(q=>{ const got=grantQuestReward(q); lines.push(`<span style="color:#ffcf6b;font-weight:bold;">✅ Quest: ${q.text}${got?` — ${got}`:''}</span>`); });
  // every 10 completed NORMAL quests unlocks the special mega-quest (the mega itself doesnt count toward the next)
  const normalDone = completed.filter(q=>!(QUEST_BY_ID[q.id]&&QUEST_BY_ID[q.id].mega)).length;
  if(creditQuestsDone(normalDone)) lines.push(`<span style="color:#ffd6ff;font-weight:bold;">✦ MEGA-QUEST unlocked! Complete it to earn a Mythic Masters pack!</span>`);
  // refill any completed quest slots + persist
  save.quests=save.quests.filter(s=>!s.done); ensureQuests();
  // new game modes unlocked by crossing a lifetime-trophy threshold this match
  if(justUnlockedModes && justUnlockedModes.length){
    justUnlockedModes.forEach(m=>lines.push(`<span style="color:#8fd3ff;font-weight:bold;">🔓 NEW MODE: ${m.label} unlocked!</span>`));
    justUnlockedModes=[];
  }
  persistSave();
  return lines;
}

// award Trophy Road points (a spendable balance that BUYS brawlers in order) AND KO-points
// (a separate spendable currency that rolls skins). Both are spent, so no surplus can ever
// pre-buy a brawler added later. lifetimePoints just tracks total trophies earned, forever.
// returns {chars:[ids], cosmetics:[ids]} of things newly obtained.
function awardPoints(pts, kos){  // --- Trophy Road: spend the balance to buy the next brawler(s) in fixed order ---
  // consume pending quest doublers for this match
  let koDoubled=false;
  if(save.doublers && save.doublers.trophy>0){ pts=Math.round(pts*2); save.doublers.trophy--; }
  if(save.doublers && save.doublers.ko>0){ kos=(kos||0)*2; save.doublers.ko--; koDoubled=true; }
  save.points+=pts;
  const lifeBefore=(save.lifetimePoints||0);
  save.lifetimePoints=lifeBefore+pts;
  // any game modes whose lifetime-trophy threshold we just crossed → announced on the reward screen
  justUnlockedModes = MODE_UNLOCKS.filter(m=> lifeBefore < m.need && save.lifetimePoints >= m.need);
  const chars=[];
  let node;
  while((node=nextBrawlerNode()) && save.points>=node.cost){
    save.points-=node.cost;                 // pay for it (balance can't stockpile past what's buyable)
    save.unlocked.push(node.id); chars.push(node.id);
  }
  // cap the leftover balance so surplus can NEVER pre-fund a brawler added in a later update:
  // - all brawlers owned  -> balance parks at 0 (nothing to buy)
  // - a next brawler left  -> keep at most (its cost - 1) so it still needs one more win to afford
  const nb=nextBrawlerNode();
  save.points = nb ? Math.min(save.points, nb.cost-1) : 0;
  // --- Rewards: spend KO-points to roll the next unlockable (skin OR emote), cost by unlock state ---
  const cosmetics=[]; const emotes=[]; const currencyPayouts=[];
  // KO-points per kill: solo modes (FFA + Silverdome) pay full; team modes pay half (kills are cheaper there)
  const koPts = TEAMED() ? 10 : SKIN_PTS_PER_KO;
  save.skinPoints += (kos||0)*koPts;
  while(save.skinPoints>=skinCost() && availableUnlockables().length){
    save.skinPoints-=skinCost();             // spend this milestone's cost
    const pool=availableUnlockables();
    const pick=pool[Math.floor(Math.random()*pool.length)];
    if(pick.kind==='emote'){
      save.emotes.push(pick.id); emotes.push(pick.id);
    } else {
      // for skins, respect the common-before-rare order within the chosen character
      const cid=COSMETICS[pick.id].char;
      const id=nextSkinForChar(cid) || pick.id;
      save.cosmetics.push(id); cosmetics.push(id);
      if(!save.equipped[cid]) save.equipped[cid]=id;   // auto-equip if nothing equipped yet
    }
  }
  // don't let KO-points balloon when there's nothing left to earn
  // Nothing left to unlock? Instead of capping (and giving you "nothing"), convert each KO-milestone into a
  // modest currency payout — rotating across the currencies of the game modes you've actually unlocked, so
  // the KO grind always pays into a shop you can use.
  if(!availableUnlockables().length){
    // {currency-field, mode-id that must be unlocked, per-milestone payout, reward label}
    const PAYOUTS=[
      {cur:'tokens',   mode:'arena',    amt:3, label:'🎟 {n} Silver Tokens'},
      {cur:'pearls',   mode:'pearl',    amt:2, label:'🫧 {n} Pearls'},
      {cur:'tickets',  mode:'payload',  amt:2, label:'🎟️ {n} Prize Tickets'},
      {cur:'acorns',   mode:'ctf',      amt:2, label:'🌰 {n} Acorns'},
      {cur:'stardust', mode:'whiteout', amt:3, label:'✨ {n} Stardust'},
      {cur:'atoms',    mode:'binas',    amt:2, label:'⚛️ {n} Atoms'}
    ].filter(p=>isModeUnlocked(p.mode));
    if(PAYOUTS.length){
      while(save.skinPoints>=skinCost()){
        save.skinPoints-=skinCost();
        const p=PAYOUTS[(save.cosmeticsClaimed||0)%PAYOUTS.length];   // rotate through the unlocked currencies
        save[p.cur]=(save[p.cur]||0)+p.amt; save.cosmeticsClaimed=(save.cosmeticsClaimed||0)+1;
        currencyPayouts.push(p.label.replace('{n}',p.amt));
      }
    } else {
      save.skinPoints=Math.min(save.skinPoints, skinCost());   // no shop unlocked yet — just cap
    }
  }
  persistSave();
  return {chars, cosmetics, emotes, koDoubled, koPts:(kos||0)*koPts, effKos:(kos||0)};
}
// resolve the display color for a character (equipped cosmetic overrides the default)
function charColor(charId){
  const cid=save.equipped&&save.equipped[charId];
  return (cid&&COSMETICS[cid])?COSMETICS[cid].color:CHARS[charId].color;
}
// equipped gear-override style for a character (rare skins), or null
function charGear(charId){
  const cid=save.equipped&&save.equipped[charId];
  return (cid&&COSMETICS[cid]&&COSMETICS[cid].gear)?COSMETICS[cid].gear:null;
}
// equipped mythic-skin morph key for a character (big transformation overlay), or null
function charMorph(charId){
  const cid=save.equipped&&save.equipped[charId];
  return (cid&&COSMETICS[cid]&&COSMETICS[cid].morph)?COSMETICS[cid].morph:null;
}


/* ---------- Global state ---------- */
let state = "title";
