let chosen = null;
let keys = {}, mouse={x:W/2,y:H/2,down:false,aiming:false,releaseFire:false};
// on-screen touch controls: left stick moves, right buttons attack (auto-aim) + super
const touch={ moveX:0, moveY:0, attacking:false, superTap:false };
let entities=[], projectiles=[], bombs=[], particles=[], floaters=[], bushes=[], trees=[], iceTrail=[], bats=[], exhaust=[], wetFloor=[], damageZones=[], cameras=[], hydrants=[], rings=[];
let player=null;
let matchTime, defeated, matchDamage=0, frame=0;   // matchDamage: total damage the player deals this match (quests; reset on start)
let gameMode = "ffa";        // "ffa" (storm royale), "relay" (2v2 Ember Relay), "arena", "pearl", or "practice"
// --- Mode unlocks: gated behind lifetime trophies so a new player isn't dropped into all modes at once.
// FFA + Practice are always open; the rest unlock in big lifetime-trophy increments.
const MODE_UNLOCKS = [
  {id:'relay',    btn:'toRelay',    label:'Ember Relay',    need:500},
  {id:'arena',    btn:'toArena',    label:'Silverdome Arena',need:1500},
  {id:'pearl',    btn:'toPearl',    label:'Pearl Rush',     need:3000},
  {id:'payload',  btn:'toPayload',  label:'Payload Panic',  need:6000},
  {id:'ctf',      btn:'toCtf',      label:'Acorn Heist',    need:10000},
  {id:'whiteout', btn:'toWhiteout', label:'Alien Whiteout', need:15000},
  {id:'binas',    btn:'toBinas',    label:'Binas Boss',     need:20000}
];
function modeNeed(id){ const m=MODE_UNLOCKS.find(x=>x.id===id); return m?m.need:0; }
function isModeUnlocked(id){ const m=MODE_UNLOCKS.find(x=>x.id===id); return !m || (save.lifetimePoints||0) >= m.need; }
let justUnlockedModes=[];   // modes whose threshold was crossed by the last match (announced on the reward screen)
// --- Interactive tutorial: a scripted first FFA-style match that reacts to what the player does.
// steps advance as the player moves, attacks, charges + fires their super, and defeats the practice bots.
const tutorial={ step:0, timer:0, movedFrames:0, hits:0, superUsed:false, done:false };
const TUTORIAL_VERSION=1;   // bump to re-show the tutorial once after a meaningful update
// Practice Plains state: free training range. Dummies auto-heal, don't score; toggle their movement.
const practice={ moving:false, shootBack:false };
// Silverdome Arena state: 1v1 gauntlet over 10 rounds, one modifier each round.
const arena={ round:0, mod:null, tokensThisRun:0, active:false };
// Ember Relay state: a torch that scores points for its carrier's team.
const relay={ torch:{x:0,y:0,carrier:null,dropTimer:0}, score:{0:0,1:0}, target:100 };
const TEAM_COLOR={0:"#ff8a3d", 1:"#4db6ff"};   // team 0 = yours (warm), team 1 = rivals (cool)
const RELAY_SLOW=0.8;          // carrier moves at 80% speed
const RESPAWN_FRAMES=300;      // 5s at 60fps
// Pearl Rush state (3v3 gem-grab): loose pearls spawn centrally; hold the lead to win.
const pearl={ loose:[], spawnCd:0, target:12, countdown:0, leadTeam:-1, peak:{0:0,1:0} };
const PEARL_COUNTDOWN=600;     // hold the lead this many frames (10s) to win
const PEARL_SLOW=0.94;         // each carried pearl barely slows you (multiplied per pearl, capped)
// Payload Panic state (3v3): each team owns a toy train on its own rail. Stand on your train while it's
// clear of enemies (or your team outnumbers them on it) to push it forward. First train to the finish wins.
const payload={ carts:[/*team0*/null,/*team1*/null], winner:-1 };
const PAYLOAD_SPEED=0.4;       // px/frame the cart rolls while being pushed (lower = slower, more contested pushes)
// Alien Whiteout state (4v4 recruit war): each team has a LEADER (never converts). Defeat a non-leader
// and they respawn on YOUR team, taking your color. Win by stealing every recruit — or most when time runs out.
const whiteout={ winner:-1, leader:[/*team0*/null,/*team1*/null], spawns:{0:[],1:[]}, timeLimit:60*60*3 };
// ---- Binas Boss: you + 2 bot allies (team 0) vs Evil Renas, a mega-boss who channels the Binas.
// He cycles three phases — 🧬 Biologie (roots + spore adds + self-heal), 🧪 Scheikunde (acid pools + gas),
// ⚡ Natuurkunde (gravity pull + lightning). Beat all his health bars (one per phase) to win.
const binas={ boss:null, phase:0, phaseNames:['Biologie','Scheikunde','Natuurkunde'], phaseIcons:['🧬','🧪','⚡'],
  cast:0, castCd:180, minions:[], acid:[], winner:-1, introTimer:0 };
const BINAS_PHASE_HP=[14000, 14000, 18000];   // health for each phase; boss refreshes to the next bar when one empties (no self-heal — raw HP instead)
const BINAS_MINION_CAP=4;
const BINAS_DOWN_FRAMES=15*60;   // a downed ally lies revivable for 15s before they're gone for good
const BINAS_REVIVE_RANGE=90;     // stand this close to a downed ally to revive them
const BINAS_REVIVE_RATE=1.4;     // reviveProg fills by this per frame while a teammate is close (~1.2s to full at 100)
const PAYLOAD_RIDE_R=64;       // how close a fighter must be to the cart center to count as "on" it
// Acorn Heist (CTF, 3v3): each team guards a base pile of acorns. Steal from the enemy base, carry it home
// to your base to score. Drop it if you're KO'd. First team to `target` delivered acorns wins.
const ctf={ bases:[/*team0*/null,/*team1*/null], loose:[], target:5, winner:-1, lead:0 };
const CTF_BASE_R=70;           // how close to a base you must be to steal/deposit
const CTF_START_PILE=5;        // acorns sitting in each base at the start
// team modes (relay + pearl + payload + ctf) share friendly-fire + team-visual logic
function TEAMED(){ return gameMode==="relay"||gameMode==="pearl"||gameMode==="payload"||gameMode==="ctf"||gameMode==="whiteout"||gameMode==="binas"; }
// storm: circular safe zone shrinks over the match; outside it hurts.
const storm={cx:0,cy:0,r:0,targetR:0,maxR:0,minR:0,delay:0};
let raf=null;

/* ---------- Input ---------- */
// 🥚 build-400 easter egg: the Konami code, checked only on the title screen (see keydown handler)
const KONAMI=['ArrowUp','ArrowUp','ArrowDown','ArrowDown','ArrowLeft','ArrowRight','ArrowLeft','ArrowRight','b','a'];
let konamiBuf=[];
addEventListener('keydown',e=>{
  initAudio();
  const k=e.key.toLowerCase();
  keys[k]=true;
  if(k==='m'){ muted=!muted; updateMuteUI(); }
  if(k==='e' && state==='play'){ playerEmote('manual'); }
  // 🥚 Konami code on the MAIN MENU only (never mid-game): ↑↑↓↓←→←→ B A → a little celebration
  if(state==='title' && !document.getElementById('titleScreen').classList.contains('hidden')){
    konamiBuf.push(e.key.length===1?k:e.key); if(konamiBuf.length>KONAMI.length) konamiBuf.shift();
    if(konamiBuf.length===KONAMI.length && KONAMI.every((key,i)=>konamiBuf[i]===key)){ konamiBuf.length=0; femboyParty(); }
  }
  if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k)) e.preventDefault();
});
addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;});
cv.addEventListener('mousemove',e=>{
  const r=cv.getBoundingClientRect();
  mouse.x=(e.clientX-r.left)*(W/r.width);
  mouse.y=(e.clientY-r.top)*(H/r.height);
});
cv.addEventListener('mousedown',()=>{ initAudio(); mouse.down=true; mouse.aiming=true; });
addEventListener('mouseup',()=>{ if(mouse.aiming){ mouse.releaseFire=true; mouse.aiming=false; } mouse.down=false; });
addEventListener('click',initAudio);
function updateMuteUI(){ const el=document.getElementById('muteBtn'); if(el) el.textContent=muted?'🔇':'🔊';
  // keep the music in sync with the mute state
  if(muted) stopMusic();
  else if(state==="play") startMusic();
}
// 🥚 build-400 easter egg celebration: a pastel confetti + hearts burst with a sweet message.
// Pure DOM overlay so it works independently of the canvas game-loop; auto-cleans after the animation.
let femboyPartyActive=false;
function femboyParty(){
  if(femboyPartyActive) return; femboyPartyActive=true;
  try{ sfx('unlock'); sfx('super'); }catch(e){}
  const wrap=document.getElementById('wrap')||document.body;
  const layer=document.createElement('div');
  layer.style.cssText='position:absolute; inset:0; z-index:50; pointer-events:none; overflow:hidden; border-radius:18px;';
  // femboy-pride pastel palette: pink / white / sky-blue
  const cols=['#ff9ecb','#ffffff','#7ec8ff','#ffc8e6','#b0e0ff','#ffd6ec'];
  const glyphs=['💖','🎀','💗','✨','🩷','💙','🤍'];
  for(let i=0;i<70;i++){
    const bit=document.createElement('div');
    const useGlyph=Math.random()<0.45;
    const size=8+Math.random()*14, left=Math.random()*100, delay=Math.random()*0.6, dur=1.8+Math.random()*1.8;
    if(useGlyph){ bit.textContent=glyphs[Math.floor(Math.random()*glyphs.length)]; bit.style.fontSize=(14+Math.random()*16)+'px'; }
    else { bit.style.width=size+'px'; bit.style.height=(size*0.6)+'px'; bit.style.background=cols[Math.floor(Math.random()*cols.length)]; bit.style.borderRadius='2px'; }
    bit.style.cssText+=`position:absolute; top:-30px; left:${left}%; opacity:0;
      animation:fbFall ${dur}s cubic-bezier(.3,.6,.5,1) ${delay}s forwards;`;
    layer.appendChild(bit);
  }
  // the sweet centered message
  const msg=document.createElement('div');
  msg.innerHTML=`<div style="font-size:clamp(30px,6vw,58px); font-weight:bold; color:#ff8ac4; text-shadow:0 3px 0 #b0507f,0 0 30px rgba(255,150,210,.8); transform:rotate(-3deg);">✨ BUILD 400 ✨</div>
    <div style="font-size:clamp(15px,2.6vw,22px); color:#eaf3ff; margin-top:10px; text-shadow:0 2px 6px rgba(0,0,0,.5);">femboys make the forest brighter 🩷</div>`;
  msg.style.cssText='position:absolute; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center; text-align:center; animation:fbPop .5s cubic-bezier(.2,1.5,.4,1) both;';
  layer.appendChild(msg);
  wrap.appendChild(layer);
  setTimeout(()=>{ layer.style.transition='opacity .6s'; layer.style.opacity='0'; setTimeout(()=>{ layer.remove(); femboyPartyActive=false; },600); }, 3200);
}


/* ---------- Helpers ---------- */
const rand=(a,b)=>a+Math.random()*(b-a);
const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));

/* =======================================================================
   TILE MAP SYSTEM
   -----------------------------------------------------------------------
   The arena is a grid of tiles. Edit MAP_LAYOUT below to redesign the map.
   Each character = one tile:
     .  grass      (walkable)
     ,  path/dirt  (walkable)
     #  log wall   (solid, blocks movement + projectiles; destructible by supers)
     B  bush       (walkable cover; blocks projectiles; destructible)
     ~  water      (solid, blocks movement; projectiles fly over)
     N  Nathan spawn   D  Daniel spawn   Y  Yassin spawn   P  player spawn
   Rows must all be the same length. The grid auto-scales to the canvas.
   ======================================================================= */
