// ---- Action-animation style per brawler ----
// Attack pose: how the body reads when the base attack fires. Types:
//   swing  = wind up + rotate a swipe (melee arcs / shotguns / bats)
//   thrust = crouch + pitch the whole body forward along the aim (jabs, spear, hard throws)
//   recoil = brace + kick backward (snipers / rapid guns)
//   lob    = lean back then arc up-and-over (grenades / anchors)
//   punch  = quick double hitch forward (fist combos)
const ATK_STYLE = {
  yassin:'punch', fionn:'swing', reshman:'thrust', dean:'swing', claire:'swing',
  stalker:'swing', evadam:'thrust', otis:'thrust', sonia:'thrust', johan:'swing',
  waitress:'swing', lars:'swing',
  nathan:'thrust', renas:'swing', robin:'recoil', milo:'recoil', jake:'recoil',
  adam:'recoil', marlin:'recoil', fluharty:'swing',
  daniel:'lob', kimchi:'lob', sanne:'lob',
  deniz:'thrust', josh:'thrust'
};
// Super pose: the "power moment". Types:
//   leap    = deep crouch then launch upward (smashes / hops)
//   surge   = brace low then explode upward with a scale-pulse (buffs, bursts, casts)
//   flourish= a spin/twirl (casters, area effects)
//   raise   = lift arms/banner overhead (rally, summons, deploys)
const SUP_STYLE = {
  adam:'leap', otis:'leap', evadam:'leap', renas:'leap',
  sonia:'raise', josh:'raise', nathan:'raise', stalker:'raise', johan:'raise',
  deniz:'flourish', kimchi:'flourish', reshman:'flourish', fluharty:'flourish', robin:'flourish',
  yassin:'surge', fionn:'surge', dean:'surge', claire:'surge', waitress:'surge',
  lars:'surge', milo:'surge', jake:'surge', daniel:'surge', sanne:'surge', marlin:'surge'
};
// how far a straight shot travels from (x,y) along (dx,dy) before hitting a wall/bush, capped at max
function rayReach(x,y,dx,dy,max){
  const step=8;
  for(let d=step; d<=max; d+=step){
    const px=x+dx*d, py=y+dy*d;
    if(blocksProjectile(tileAtPx(px,py))) return d;   // stop at the first wall/bush
  }
  return max;
}
// is there a solid WALL between two points? (used so hitscan cones don't shoot through walls)
function wallBetween(ax,ay,bx,by){
  const dx=bx-ax, dy=by-ay, len=Math.hypot(dx,dy)||1, step=8;
  for(let d=step; d<len; d+=step){
    if(tileAtPx(ax+dx/len*d, ay+dy/len*d)===TILE.WALL) return true;
  }
  return false;
}
// Kayo & Yara aim shape depends on the active form (Kayo=melee lunge, Yara=twin ranged throw)
const YARA_AIM = {shape:'twin', len:300, wide:6, sep:11};
function aimProf(f){ if(f && f.char==='kayo' && f.form==='yara') return YARA_AIM; return AIM[f.char]; }
// draw the aim preview for the player while the mouse button is held (desktop only)
function drawAimIndicator(f){
  const prof = aimProf(f); if(!prof) return;
  const a=f.aim, ang=Math.atan2(a.y,a.x);
  const col="rgba(255,255,255,.85)", fillCol="rgba(255,255,255,.16)";
  ctx.save();
  ctx.translate(f.x, f.y);
  ctx.lineCap="round"; ctx.lineJoin="round";
  const drawBeam=(len,wide,dashed)=>{
    ctx.rotate(ang);
    if(dashed) ctx.setLineDash([10,8]);
    ctx.strokeStyle=col; ctx.lineWidth=wide;
    ctx.beginPath(); ctx.moveTo(f.radius,0); ctx.lineTo(len,0); ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle=col; ctx.beginPath(); ctx.arc(len,0,Math.max(5,wide*0.7),0,6.28); ctx.fill();  // tip marker
    ctx.rotate(-ang);
  };
  if(prof.shape==='line'){
    const len=rayReach(f.x,f.y,a.x,a.y,prof.len);   // stop at walls/bushes
    drawBeam(len, prof.wide, prof.boomerang||prof.pierce);
  }
  else if(prof.shape==='curve'){
    // Fluharty: trace the actual curveball arc (same physics as the throw), stopping at a wall.
    // The NEXT throw's curve side matches how fighterAttack will compute it.
    const nextStep=((f.curveStep||0)+1)%2, side = nextStep?1:-1;
    const sp=8, perpx=-a.y, perpy=a.x, ax=perpx*0.28*side, ay=perpy*0.28*side;
    let px=f.x+a.x*f.radius, py=f.y+a.y*f.radius, vx=a.x*sp, vy=a.y*sp;
    ctx.strokeStyle=col; ctx.lineWidth=prof.wide; ctx.setLineDash([10,8]);
    ctx.beginPath(); ctx.moveTo(px-f.x, py-f.y);
    let steps=Math.round(prof.len/sp), lastx=px, lasty=py;
    for(let s=0;s<steps;s++){
      vx+=ax; vy+=ay; px+=vx; py+=vy;
      if(tileAtPx(px,py)===TILE.WALL) break;
      ctx.lineTo(px-f.x, py-f.y); lastx=px; lasty=py;
    }
    ctx.stroke(); ctx.setLineDash([]);
    ctx.fillStyle=col; ctx.beginPath(); ctx.arc(lastx-f.x, lasty-f.y, Math.max(5,prof.wide*0.7),0,6.28); ctx.fill();
  }
  else if(prof.shape==='combo'){
    // Lars: a directed melee arc up close + a projectile line for range (shows both options)
    ctx.rotate(ang);
    ctx.fillStyle=fillCol; ctx.strokeStyle=col; ctx.lineWidth=2;
    ctx.beginPath(); ctx.moveTo(0,0); ctx.arc(0,0,prof.meleeRadius,-0.6,0.6); ctx.closePath(); ctx.fill(); ctx.stroke();
    ctx.rotate(-ang);
    const len=rayReach(f.x,f.y,a.x,a.y,prof.len);
    drawBeam(len, prof.wide, false);
  }
  else if(prof.shape==='fan'){
    // Josh: three separate rays (one straight, two diagonal), each stopping at obstacles
    [-prof.spread,0,prof.spread].forEach(off=>{
      const ca=Math.cos(ang+off), sa=Math.sin(ang+off);
      const len=rayReach(f.x,f.y,ca,sa,prof.len);
      ctx.strokeStyle=col; ctx.lineWidth=prof.wide;
      ctx.beginPath(); ctx.moveTo(ca*f.radius,sa*f.radius); ctx.lineTo(ca*len,sa*len); ctx.stroke();
      ctx.fillStyle=col; ctx.beginPath(); ctx.arc(ca*len,sa*len,Math.max(4,prof.wide*0.6),0,6.28); ctx.fill();
    });
  }
  else if(prof.shape==='twin'){
    const px=-a.y*prof.sep, py=a.x*prof.sep;
    [1,-1].forEach(s=>{
      const ox=px*s, oy=py*s;
      const len=rayReach(f.x+ox,f.y+oy,a.x,a.y,prof.len);
      ctx.strokeStyle=col; ctx.lineWidth=prof.wide;
      ctx.beginPath(); ctx.moveTo(ox+a.x*f.radius,oy+a.y*f.radius); ctx.lineTo(ox+a.x*len,oy+a.y*len); ctx.stroke();
    });
  }
  else if(prof.shape==='cone'){
    ctx.rotate(ang);
    ctx.fillStyle=fillCol; ctx.strokeStyle=col; ctx.lineWidth=2;
    ctx.beginPath(); ctx.moveTo(0,0); ctx.arc(0,0,prof.range,-prof.spread,prof.spread); ctx.closePath();
    ctx.fill(); ctx.stroke();
    ctx.rotate(-ang);
  }
  else if(prof.shape==='box'){
    ctx.rotate(ang);
    ctx.fillStyle=fillCol; ctx.strokeStyle=col; ctx.lineWidth=2;
    ctx.beginPath(); ctx.rect(f.radius,-prof.halfW, prof.range-f.radius, prof.halfW*2); ctx.fill(); ctx.stroke();
    ctx.rotate(-ang);
  }
  else if(prof.shape==='melee'){
    const mx=a.x*prof.reach, my=a.y*prof.reach, rad=prof.radius||prof.reach*0.5;
    // guide line from the fighter out to the strike zone
    ctx.strokeStyle=col; ctx.lineWidth=2; ctx.setLineDash([8,7]);
    ctx.beginPath(); ctx.moveTo(a.x*f.radius,a.y*f.radius); ctx.lineTo(mx,my); ctx.stroke(); ctx.setLineDash([]);
    ctx.fillStyle=fillCol; ctx.strokeStyle=col; ctx.lineWidth=2;
    ctx.beginPath(); ctx.arc(mx,my,rad,0,6.28); ctx.fill(); ctx.stroke();
  }
  else if(prof.shape==='ring'){
    ctx.fillStyle=fillCol; ctx.strokeStyle=col; ctx.lineWidth=2;
    ctx.beginPath(); ctx.arc(0,0,prof.reach,0,6.28); ctx.fill(); ctx.stroke();
  }
  else if(prof.shape==='lob'){
    // landing point = cursor, capped at range; show a blast circle there
    const mx=mouse.x+cam.x, my=mouse.y+cam.y;
    let d=Math.hypot(mx-f.x,my-f.y); d=Math.min(d,prof.range)||1;
    const lx=a.x*d, ly=a.y*d;
    ctx.strokeStyle=col; ctx.lineWidth=2; ctx.setLineDash([8,7]);
    ctx.beginPath(); ctx.moveTo(f.radius*a.x,f.radius*a.y); ctx.lineTo(lx,ly); ctx.stroke(); ctx.setLineDash([]);
    ctx.fillStyle=fillCol; ctx.strokeStyle=col;
    ctx.beginPath(); ctx.arc(lx,ly,prof.blast,0,6.28); ctx.fill(); ctx.stroke();
  }
  else if(prof.shape==='dash'){
    // travel to a point (fixed distance, or up to cursor), impact circle at the end
    let d=prof.range;
    if(!prof.fixed){ const mx=mouse.x+cam.x, my=mouse.y+cam.y; d=Math.min(Math.hypot(mx-f.x,my-f.y),prof.range)||1; }
    const lx=a.x*d, ly=a.y*d;
    ctx.strokeStyle=col; ctx.lineWidth=3; ctx.setLineDash([9,7]);
    ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(lx,ly); ctx.stroke(); ctx.setLineDash([]);
    ctx.fillStyle=fillCol; ctx.strokeStyle=col; ctx.lineWidth=2;
    ctx.beginPath(); ctx.arc(lx,ly,prof.radius,0,6.28); ctx.fill(); ctx.stroke();
  }
  ctx.restore();
}

// Fluharty bots: pre-bend the aim so the curveball's sideways drift lands on the target.
// The ball launches along `aim` at sp=8 with perpendicular accel 0.28*side; over the flight
// it drifts ~0.5*accel*t^2 sideways (t = dist/sp frames). We rotate aim AGAINST that drift.
function aimForCurve(e, dist){
  const sp=8, accel=0.28;
  const nextStep=((e.curveStep||0)+1)%2, side = nextStep?1:-1;   // side the NEXT throw will curve
  const t=Math.min(dist/sp, 90);                                 // flight time in frames (capped)
  const drift=0.5*accel*t*t;                                     // lateral offset at the target
  const corr = -side * Math.atan2(drift, Math.max(dist,1)) * 0.9; // aim opposite the curve
  const cc=Math.cos(corr), ss=Math.sin(corr), x=e.aim.x, y=e.aim.y;
  e.aim={ x: x*cc - y*ss, y: x*ss + y*cc };
}

// how far a lob-brawler throws this shot: player aims at cursor (capped at range), bots at their target.
function lobDistance(f, range){
  if(f.isPlayer){
    const mx=mouse.x+cam.x, my=mouse.y+cam.y;
    let d=Math.hypot(mx-f.x,my-f.y);
    return clamp(d, 60, range) || range;
  }
  // bot: throw toward its current target's distance, capped
  const t=f.ai && f.ai.target;
  if(t && !t.dead){ return clamp(dist(f,t), 80, range); }
  return range;
}
// Themed attack sparkle for pack skins that don't already reskin their own projectile/effect.
