  // --- Nature ---
  nat_log:      {cols:["#8a5e34","#5a8a3a"]},    // mossy log: bark chips + moss
  nat_bamboo:   {cols:["#5a9a3a","#b8d88a"]},    // bamboo: green leaf shards
  nat_seal:     {cols:["#8a94a0","#e8f4ff"]},    // seal: cold sea-spray droplets
  nat_squirrel: {cols:["#a0602e","#e0b060"]},    // squirrel: acorn bits + fur
  nat_flytrap:  {cols:["#4a9a3a","#c8332a"]},    // venus flytrap: green + red-throat bits
  nat_bear:     {cols:["#8a5e34","#3a2416"]},    // bear: fur + claw-dust
  nat_mushroom: {cols:["#e0402e","#f0e2cf"]},    // toadstool: red cap flecks + spores
  nat_raccoon:  {cols:["#8a9098","#3a3f46"]},    // raccoon: grey trash-scatter
  nat_rose:     {cols:["#d81e5b","#3a7a26"]},    // thorn rose: petals + thorns
  nat_bee:      {cols:["#f2b81e","#3a2a10"]},    // bee queen: pollen + stripes
  nat_hare:     {cols:["#b59a76","#e8e0d0"]},    // hare: kicked grass + fur tuft
  nat_owl:      {cols:["#8a6a44","#e8dcc0"]},    // owl: drifting feathers
