  spc_hologram: {cols:["#3ad0ff","#b7f0ff","#7affff"]}    // Hologram: blue data-pixels
  ,spc_aurora:   {cols:["#3ae0a0","#8affd0","#b58aff"]}   // Aurora: green-teal polar light + violet shimmer
  ,spc_asteroid: {cols:["#8a7a68","#b0a090","#5a4a3a"]}   // Asteroid Belt: grey-brown rock debris
