    ctx.lineTo(R*0.42,R*0.5); ctx.quadraticCurveTo(R*0.58,R*0.35,R*0.48,-R*0.45);
    ctx.quadraticCurveTo(0,-R*0.62,-R*0.48,-R*0.45); ctx.fill();
    // tank-top straps (skin showing at shoulders)
    ctx.fillStyle=skin;
    ctx.beginPath(); ctx.ellipse(-R*0.34,-R*0.5,R*0.12,R*0.16,0,0,6.28); ctx.fill();
    ctx.beginPath(); ctx.ellipse(R*0.34,-R*0.5,R*0.12,R*0.16,0,0,6.28); ctx.fill();
    ctx.fillStyle=shirt;
    ctx.beginPath(); ctx.roundRect(-R*0.42,-R*0.5,R*0.16,R*0.3,4); ctx.fill();
    ctx.beginPath(); ctx.roundRect(R*0.26,-R*0.5,R*0.16,R*0.3,4); ctx.fill();
