    ctx.fillStyle="#1b2b33"; ctx.strokeStyle="#0d1519"; ctx.lineWidth=2;
    ctx.beginPath(); ctx.roundRect(R*0.04-hr*0.62,hy-hr*0.28,hr*0.5,hr*0.34,4); ctx.fill(); ctx.stroke();
    ctx.beginPath(); ctx.roundRect(R*0.04+hr*0.12,hy-hr*0.28,hr*0.5,hr*0.34,4); ctx.fill(); ctx.stroke();
