    ctx.beginPath();
    ctx.moveTo(-R*0.5,-R*0.4); ctx.quadraticCurveTo(-R*0.6,R*0.4,-R*0.42,R*0.52);
    ctx.lineTo(R*0.42,R*0.52); ctx.quadraticCurveTo(R*0.6,R*0.4,R*0.5,-R*0.4);
    ctx.quadraticCurveTo(0,-R*0.62,-R*0.5,-R*0.4); ctx.fill();
    // hoodie side shade + pocket + zipper
    ctx.fillStyle="rgba(0,0,0,.18)"; ctx.beginPath(); ctx.ellipse(R*0.3,R*0.1,R*0.2,R*0.44,0,0,6.28); ctx.fill();
    ctx.strokeStyle=hoodDk; ctx.lineWidth=Math.max(2,R*0.06); ctx.beginPath(); ctx.moveTo(0,-R*0.5); ctx.lineTo(0,R*0.5); ctx.stroke();
    ctx.fillStyle=hoodDk; ctx.beginPath(); ctx.roundRect(-R*0.26,R*0.18,R*0.52,R*0.24,5); ctx.fill(); // kangaroo pocket
    // back arm tucked in
