    ctx.fillStyle=skin; ctx.beginPath(); ctx.arc(-R*0.5,R*0.18,R*0.14,0,6.28); ctx.fill();
    // forward arm holding a small handheld camera — juts forward + flashes on a shot
    let camX=0, flash=0;
    if(e && e.atkAnim>0){ const ap=1-e.atkAnim/18, rel=Math.sin(ap*Math.PI); camX=rel*R*0.32; flash=e.atkAnim/18; }
    ctx.fillStyle=hood; ctx.beginPath(); ctx.roundRect(R*0.42+camX*0.5,-R*0.28,R*0.46,R*0.2,7); ctx.fill();
    ctx.fillStyle=skin; ctx.beginPath(); ctx.arc(R*0.9+camX,-R*0.18,R*0.13,0,6.28); ctx.fill(); // hand
    // handheld camera in the hand
    ctx.fillStyle="#332a44"; ctx.strokeStyle="#1a1226"; ctx.lineWidth=2;
    ctx.beginPath(); ctx.roundRect(R*0.86+camX,-R*0.34,R*0.34,R*0.26,4); ctx.fill(); ctx.stroke();
    ctx.beginPath(); ctx.arc(R*1.16+camX,-R*0.21,R*0.09,0,6.28); ctx.fillStyle="#120c1e"; ctx.fill(); ctx.stroke();
    ctx.beginPath(); ctx.arc(R*1.16+camX,-R*0.21,R*0.04,0,6.28); ctx.fillStyle="#ff4a4a"; ctx.fill(); // lens glint
    // rec light
    ctx.beginPath(); ctx.arc(R*0.9+camX,-R*0.3,R*0.03,0,6.28); ctx.fillStyle="#ff3b3b"; ctx.fill();
    // camera flash burst on the shot
    if(flash>0){ ctx.fillStyle="rgba(255,255,255,"+(flash*0.85)+")"; ctx.beginPath(); ctx.arc(R*1.24+camX,-R*0.21,R*0.22*flash+R*0.05,0,6.28); ctx.fill(); }
    // head (mostly hidden under hood)
    const hy=-R*0.82, hr=R*0.42;
    ctx.fillStyle=skin; ctx.beginPath(); ctx.arc(R*0.02,hy,hr,0,6.28); ctx.fill();
    // hood shadow over the face (dark crescent covering the top half)
    ctx.fillStyle="rgba(8,4,16,.72)";
    ctx.beginPath(); ctx.arc(R*0.02,hy-hr*0.12,hr*0.9,Math.PI*0.98,Math.PI*2.02); ctx.fill();
    ctx.beginPath(); ctx.rect(R*0.02-hr*0.9,hy-hr*1.0,hr*1.8,hr*0.8); ctx.fill();
