      ctx.strokeStyle="#5e4628"; ctx.lineWidth=1.5;
      for(let fy=R*0.0; fy<R*0.42; fy+=R*0.12){ for(let fx=-R*0.3; fx<=R*0.3; fx+=R*0.15){
        ctx.beginPath(); ctx.arc(fx,fy,R*0.08,0.2,Math.PI-0.2); ctx.stroke(); } }
