    const robot = e && e.skinMorph==='toy_robot';   // Tin Trooper: whole beagle becomes a wind-up tin robot
    const cerb = e && e.skinMorph==='cerberus';      // Cerberus: recolor the whole hound to hellhound black-brown so the body matches the extra heads
    const log = e && e.skinMorph==='nat_log';   // Mossy Log: the hound's capsule body becomes a bark log w/ rings, moss + a leafy twig
    const lander = e && e.skinMorph==='spc_lander';   // Lunar Lander: the spacesuit becomes a metallic lander hull w/ gold foil
