      ctx.fillStyle="#4e3419"; ctx.beginPath(); ctx.ellipse(-R*0.15,R*0.06,R*0.1,R*0.13,0,0,6.28); ctx.fill();   // knot hole
      ctx.fillStyle="#2a1c0e"; ctx.beginPath(); ctx.ellipse(-R*0.15,R*0.06,R*0.05,R*0.07,0,0,6.28); ctx.fill();
      // green moss clumps along the top of the log
      ctx.fillStyle="#5a8a3a";
      [[-0.4,-0.34],[0.0,-0.4],[0.34,-0.32]].forEach(p=>{ ctx.beginPath(); ctx.ellipse(R*p[0],R*p[1],R*0.16,R*0.09,0,0,6.28); ctx.fill(); });
      ctx.fillStyle="#7ab84a";
      [[-0.34,-0.4],[0.08,-0.46],[0.28,-0.38]].forEach(p=>{ ctx.beginPath(); ctx.arc(R*p[0],R*p[1],R*0.05,0,6.28); ctx.fill(); });
      // a little leafy twig sprouting up from the back
      ctx.strokeStyle="#6a4626"; ctx.lineWidth=R*0.04; ctx.lineCap="round";
      ctx.beginPath(); ctx.moveTo(-R*0.2,-R*0.36); ctx.quadraticCurveTo(-R*0.28,-R*0.7,-R*0.12,-R*0.86); ctx.stroke();
      ctx.fillStyle="#4a8a2e"; ctx.strokeStyle="#2f6a1e"; ctx.lineWidth=1;
      ctx.save(); ctx.translate(-R*0.12,-R*0.84); ctx.rotate(-0.6); ctx.beginPath(); ctx.ellipse(R*0.12,0,R*0.14,R*0.06,0,0,6.28); ctx.fill(); ctx.stroke(); ctx.restore();
      ctx.save(); ctx.translate(-R*0.18,-R*0.72); ctx.rotate(-2.2); ctx.beginPath(); ctx.ellipse(R*0.1,0,R*0.12,R*0.05,0,0,6.28); ctx.fill(); ctx.stroke(); ctx.restore();
      // cute puppy face on the sawn ring-END (drawn last, on top of the rings) — dark so it pops off the wood
