      ctx.fillStyle="rgba(255,255,255,0.5)"; ctx.beginPath(); ctx.arc(fex-R*0.09,fey-R*0.01,R*0.016,0,6.28); ctx.arc(fex+R*0.05,fey-R*0.01,R*0.016,0,6.28); ctx.fill();
