      // tiny dark nose + a happy little smile
      ctx.fillStyle="#1a0e04"; ctx.beginPath(); ctx.arc(fex,fey+R*0.05,R*0.03,0,6.28); ctx.fill();
      ctx.strokeStyle="#1a0e04"; ctx.lineWidth=R*0.025; ctx.lineCap="round";
      ctx.beginPath(); ctx.moveTo(fex,fey+R*0.08); ctx.quadraticCurveTo(fex-R*0.06,fey+R*0.15,fex-R*0.1,fey+R*0.1); ctx.moveTo(fex,fey+R*0.08); ctx.quadraticCurveTo(fex+R*0.06,fey+R*0.15,fex+R*0.1,fey+R*0.1); ctx.stroke();
