      ctx.fillStyle="#e0b888"; ctx.beginPath(); ctx.ellipse(0,hy+hr*0.35,hr*0.34,hr*0.26,0,0,6.28); ctx.fill();
      ctx.fillStyle="#2a1c12"; ctx.beginPath(); ctx.arc(0,hy+hr*0.2,hr*0.1,0,6.28); ctx.fill();
