    ctx.fillStyle=skin; ctx.beginPath(); ctx.roundRect(-R*0.07,-R*0.56,R*0.14,R*0.16,3); ctx.fill(); // neck
    const hy=-R*0.94, hr=R*0.42;
    ctx.fillStyle=skin; ctx.beginPath(); ctx.arc(0,hy,hr,0,6.28); ctx.fill();
    ctx.fillStyle=skinDk; ctx.beginPath(); ctx.ellipse(0,hy+hr*0.5,hr*0.6,hr*0.34,0,0,Math.PI); ctx.fill(); // slight jaw (adult)
    // sneaky grin
    ctx.strokeStyle=shade(skin,-40); ctx.lineWidth=R*0.05; ctx.lineCap="round";
    ctx.beginPath(); ctx.arc(hr*0.06,hy+hr*0.32,hr*0.3,0.15,Math.PI-0.35); ctx.stroke();
    // black domino mask across the eyes
    ctx.fillStyle="#22242e"; ctx.beginPath();
