    ctx.quadraticCurveTo(hr*0.86,hy+hr*0.16,hr*0.52,hy+hr*0.16);
    ctx.quadraticCurveTo(0,hy+hr*0.04,-hr*0.52,hy+hr*0.16);
    ctx.quadraticCurveTo(-hr*0.86,hy+hr*0.16,-hr*0.78,hy-hr*0.26); ctx.closePath(); ctx.fill();
    // eyes peeking through the mask
    ctx.fillStyle="#fff";
    ctx.beginPath(); ctx.arc(-hr*0.3,hy-hr*0.06,hr*0.12,0,6.28); ctx.arc(hr*0.3,hy-hr*0.06,hr*0.12,0,6.28); ctx.fill();
    ctx.fillStyle="#22242e";
    ctx.beginPath(); ctx.arc(-hr*0.26,hy-hr*0.06,hr*0.06,0,6.28); ctx.arc(hr*0.34,hy-hr*0.06,hr*0.06,0,6.28); ctx.fill();
