    ctx.fillStyle=gi; ctx.beginPath(); ctx.roundRect(R*0.5,-R*0.34,R*0.28,R*0.24,10); ctx.fill(); // front upper arm (sleeve)
    ctx.fillStyle=skin; // forearm + big fist punching forward (jabs out on attack, then retracts)
    let jab=0;
    if(e && e.atkAnim>0){ const ap=1-e.atkAnim/18, wind=ap<0.25?ap/0.25:0, rel=ap<0.25?0:Math.sin(((ap-0.25)/0.75)*Math.PI);
      jab = -R*0.22*wind + rel*R*0.6; }
