    // headset, sleek jacket, a long railgun aimed forward with a scope. Body-color = jacket/cap accents.
    const soldier = e && e.skinMorph==='toy_soldier';   // Toy Soldier: flat matte army-green plastic + a base slab
    const hare = e && e.skinMorph==='nat_hare';   // Hare: grey-brown fur, long upright ears, pink nose, cotton tail
