      // luminous icy comet: frost-white suit, bright ice-blue accents, pale frozen skin, glowing cyan glass
      suit="#eafcff"; accent="#8fd0ff"; accentDk="#4a90d0"; skin="#cfeaff"; skinDk="#9ac6e8";
      metal="#6aa8d8"; metalDk="#3a6a9a"; glass="#b7f0ff";
