    ctx.beginPath(); ctx.moveTo(-R*0.34,-R*0.44); ctx.lineTo(-R*0.18,-R*0.44); ctx.lineTo(-R*0.24,R*0.42); ctx.lineTo(-R*0.34,R*0.42); ctx.closePath(); ctx.fill();
    ctx.beginPath(); ctx.moveTo(R*0.34,-R*0.44); ctx.lineTo(R*0.18,-R*0.44); ctx.lineTo(R*0.24,R*0.42); ctx.lineTo(R*0.34,R*0.42); ctx.closePath(); ctx.fill();
    ctx.strokeStyle=accentDk; ctx.lineWidth=R*0.03; ctx.beginPath(); ctx.moveTo(0,-R*0.42); ctx.lineTo(0,R*0.4); ctx.stroke(); // zip
