    let mkick=0; if(e && e.atkAnim>0){ const ap=1-e.atkAnim/18; mkick=-Math.sin(ap*Math.PI)*R*0.3; }
    ctx.save(); ctx.translate(mkick,0);
    ctx.fillStyle=suit;
    ctx.beginPath(); ctx.roundRect(R*0.2,-R*0.3,R*0.34,R*0.16,7); ctx.fill(); // front arm
    ctx.fillStyle=skin;
    ctx.beginPath(); ctx.arc(R*0.54,-R*0.22,R*0.1,0,6.28); ctx.fill();

    // --- long railgun aimed forward (his piercing Railshot) ---
    ctx.fillStyle=metal; ctx.beginPath(); ctx.roundRect(R*0.3,-R*0.3,R*0.9,R*0.16,4); ctx.fill();   // barrel
    ctx.fillStyle=metalDk; ctx.beginPath(); ctx.roundRect(R*0.3,-R*0.16,R*0.24,R*0.18,3); ctx.fill(); // grip/body
    ctx.fillStyle=accent; ctx.beginPath(); ctx.roundRect(R*0.52,-R*0.36,R*0.3,R*0.08,3); ctx.fill();  // scope rail (accent)
