    ctx.fillStyle=glass; ctx.beginPath(); ctx.arc(R*1.24,-R*0.22,R*0.05,0,6.28); ctx.fill();           // muzzle glow
    ctx.globalAlpha=0.5; ctx.fillStyle="#bff0ff"; ctx.beginPath(); ctx.arc(R*1.32,-R*0.22,R*0.09,0,6.28); ctx.fill(); ctx.globalAlpha=1;
