    const hy=-R*0.68, hr=R*0.42;
    ctx.fillStyle=skin; ctx.beginPath(); ctx.arc(0,hy,hr,0,6.28); ctx.fill();
    ctx.fillStyle=skinDk; ctx.beginPath(); ctx.ellipse(0,hy+hr*0.5,hr*0.55,hr*0.3,0,0,Math.PI); ctx.fill(); // jaw
    // focused eyes (sharp)
    ctx.strokeStyle="#2a2018"; ctx.lineWidth=R*0.06; ctx.lineCap="round";
    ctx.beginPath(); ctx.moveTo(-hr*0.5,hy-hr*0.02); ctx.lineTo(-hr*0.14,hy+hr*0.06); ctx.stroke();
