    ctx.strokeStyle=metalDk; ctx.lineWidth=R*0.04; // mic boom
    ctx.beginPath(); ctx.moveTo(hr*0.9,hy+hr*0.2); ctx.quadraticCurveTo(hr*0.5,hy+hr*0.7,hr*0.05,hy+hr*0.55); ctx.stroke();
    ctx.fillStyle=accent; ctx.beginPath(); ctx.arc(hr*0.05,hy+hr*0.55,hr*0.07,0,6.28); ctx.fill();
