      ctx.strokeStyle="rgba(80,66,50,0.6)"; ctx.lineWidth=R*0.012; ctx.lineCap="round";
      for(let s=-1;s<=1;s+=2){ for(let w=0;w<2;w++){ ctx.beginPath(); ctx.moveTo(s*hr*0.1,hy+hr*0.36+w*hr*0.08); ctx.lineTo(s*hr*0.62,hy+hr*0.28+w*hr*0.14); ctx.stroke(); } }
