      ctx.strokeStyle="#3f7a26"; ctx.lineWidth=R*0.06; ctx.lineCap="round";
      for(let sy=-R*0.34; sy<R*0.9; sy+=R*0.26){ ctx.beginPath(); ctx.moveTo(-R*0.34,sy); ctx.quadraticCurveTo(0,sy+R*0.05,R*0.34,sy); ctx.stroke(); }
      ctx.strokeStyle="#7ab84a"; ctx.lineWidth=R*0.02;   // pale highlight just above each node
      for(let sy=-R*0.34; sy<R*0.9; sy+=R*0.26){ ctx.beginPath(); ctx.moveTo(-R*0.3,sy-R*0.05); ctx.lineTo(R*0.3,sy-R*0.05); ctx.stroke(); }
