      ctx.beginPath(); ctx.moveTo(R*0.5,boxTop+R*0.14); ctx.lineTo(R*0.64,boxTop+R*0.14); ctx.lineTo(R*0.64,boxTop+R*0.02); ctx.stroke();
      ctx.fillStyle="#8a5a2a"; ctx.beginPath(); ctx.arc(R*0.64,boxTop,R*0.05,0,6.28); ctx.fill();
