      ctx.beginPath(); ctx.moveTo(0,boxTop);
      for(let k=0;k<3;k++){ const y0=boxTop-k*R*0.1+bounce; ctx.lineTo(R*0.2,y0-R*0.05); ctx.lineTo(-R*0.2,y0-R*0.1); }
