    ctx.beginPath(); ctx.roundRect(R*0.4+jheaveX*0.4,-R*0.1+jheaveY*0.4,R*0.22,R*0.42,8); ctx.fill();
    ctx.fillStyle=skin;
    ctx.beginPath(); ctx.arc(-R*0.5+jheaveX*0.6,R*0.28+jheaveY*0.7,R*0.11,0,6.28); ctx.fill();
    ctx.beginPath(); ctx.arc(R*0.5+jheaveX,R*0.28+jheaveY,R*0.11,0,6.28); ctx.fill();
