      ctx.fillStyle="#e0433a"; ctx.beginPath(); ctx.arc(0,hy+hr*0.16,hr*0.13,0,6.28); ctx.fill();
      ctx.fillStyle="rgba(255,90,120,.5)"; ctx.beginPath(); ctx.arc(-hr*0.5,hy+hr*0.3,hr*0.15,0,6.28); ctx.arc(hr*0.5,hy+hr*0.3,hr*0.15,0,6.28); ctx.fill();
