          g.beginPath(); g.moveTo(ex-hr*0.08,ey); g.quadraticCurveTo(ex,ey-hr*0.5*flick,ex+hr*0.04,ey-hr*0.34*flick); g.quadraticCurveTo(ex+hr*0.1,ey-hr*0.1,ex+hr*0.08,ey); g.closePath(); g.fill();
