        g.fillStyle="#7a1f18"; g.beginPath(); g.moveTo(-R*0.6,R*0.1); g.lineTo(-R*0.72,-R*0.02); g.lineTo(-R*0.5,-R*0.02); g.closePath(); g.fill();
