        const sway=Math.sin(t*0.1)*R*0.2;
        const tg=g.createLinearGradient(0,R*0.5,0,R*1.5); tg.addColorStop(0,"#2aa6c6"); tg.addColorStop(1,"#8ff0e6");
        g.fillStyle=tg; g.beginPath(); g.moveTo(-R*0.2,R*0.5); g.quadraticCurveTo(-R*0.1,R*1.0,-R*0.5+sway,R*1.5);
        g.quadraticCurveTo(0,R*1.15,R*0.5+sway,R*1.5); g.quadraticCurveTo(R*0.1,R*1.0,R*0.2,R*0.5); g.closePath(); g.fill();
