        const grd=g.createLinearGradient(0,-R*0.4,0,R*1.2); grd.addColorStop(0,"rgba(175,210,220,0.85)"); grd.addColorStop(0.6,"rgba(150,190,205,0.7)"); grd.addColorStop(1,"rgba(150,190,205,0)");
        g.fillStyle=grd; g.strokeStyle="rgba(200,230,235,0.4)"; g.lineWidth=1.5;
