          g.fillStyle=grd; g.beginPath(); g.moveTo(0,-R*0.08); g.quadraticCurveTo(s*R*1.0,-R*0.35,s*R*1.1,R*0.05); g.quadraticCurveTo(s*R*0.6,R*0.05,0,R*0.18); g.closePath(); g.fill();
