      if(p.type==="fastball"){ ctx.globalAlpha=0.35; ctx.fillStyle="#c8944a"; ctx.beginPath(); ctx.arc(0,0,p.r*1.7,0,6.28); ctx.fill(); ctx.globalAlpha=1; }
      const g=ctx.createRadialGradient(-p.r*0.3,-p.r*0.2,1,0,0,p.r); g.addColorStop(0,"#e0b070"); g.addColorStop(1,"#a06a2a");
