      ctx.beginPath(); ctx.moveTo(0,-p.r*0.8);
      let px=0,py=-p.r*0.8; for(let i=1;i<=5;i++){ const f=i/5; px=Math.sin(frame*0.2+f*4)*p.r*0.5*f; py=-p.r*0.8+f*len; ctx.lineTo(px,py); }
      ctx.stroke();
