      for(let i=1;i<=4;i++){ const f=i/5; ctx.beginPath(); ctx.arc(Math.sin(frame*0.2+f*4)*p.r*0.5*f, -p.r*0.8+f*len, p.r*0.14,0,6.28); ctx.fill(); }
