        ctx.beginPath(); ctx.moveTo(0,-p.r*0.55); ctx.lineTo(0,p.r*0.55); ctx.moveTo(-p.r*0.5,0); ctx.lineTo(p.r*0.5,0); ctx.stroke();   // cell grid
