      ctx.fillStyle=bg; ctx.beginPath(); ctx.roundRect(-p.r*0.45,-p.r*0.5,p.r*0.9,p.r,p.r*0.2); ctx.fill();
      ctx.fillStyle="#e0c060"; ctx.beginPath(); ctx.rect(-p.r*0.3,-p.r*0.35,p.r*0.6,p.r*0.7); ctx.fill();   // gold-foil panel
      // dish antenna
      ctx.fillStyle="#c0c8d4"; ctx.beginPath(); ctx.ellipse(0,-p.r*0.7,p.r*0.4,p.r*0.22,0,0,6.28); ctx.fill();
      ctx.strokeStyle="#8fd3ff"; ctx.lineWidth=1.2; ctx.beginPath(); ctx.moveTo(0,-p.r*0.5); ctx.lineTo(0,-p.r*0.72); ctx.stroke();
      // blue signal ping pulsing off the dish
