      for(let k=0;k<4;k++){ ctx.fillStyle=cols[k]; ctx.beginPath(); ctx.moveTo(0,0); ctx.arc(0,0,p.r*1.05,k*1.57,(k+1)*1.57); ctx.closePath(); ctx.globalAlpha=0.85; ctx.fill(); }
      ctx.globalAlpha=1; ctx.fillStyle="rgba(255,255,255,.7)"; ctx.beginPath(); ctx.arc(-p.r*0.3,-p.r*0.3,p.r*0.2,0,6.28); ctx.fill();
      if(p.phase==="planted"){ ctx.globalAlpha=0.25; ctx.fillStyle="#3a86ff"; ctx.beginPath(); ctx.arc(0,0,p.r*1.1,0,6.28); ctx.fill(); ctx.globalAlpha=1; }
