    ctx.rotate(Math.atan2(p.vy,p.vx));
    ctx.globalAlpha=0.5; ctx.fillStyle=fn?"#9fe86b":"#dfe6ff"; ctx.beginPath(); ctx.ellipse(0,0,p.r*2.2,p.r*1.1,0,0,6.28); ctx.fill(); ctx.globalAlpha=1;
