      ctx.globalAlpha=0.5; ctx.fillStyle="#bfe0ff"; ctx.beginPath(); ctx.ellipse(-p.r*1.2,0,p.r*3.0,p.r*0.4,0,0,6.28); ctx.fill();   // lance streak
