/* ---------- Silverdome Arena: round result ---------- */
function endArenaRound(){
  const won=!player.dead;
  const t=document.getElementById('overTitle'); document.getElementById('overScreen').dataset.result = (typeof won!=='undefined'&&won)?'win':'lose';
  const nextBtn=document.getElementById('nextRoundBtn');
  const shopBtn=document.getElementById('shopFromOver');
  const againBtn=document.getElementById('againBtn');
  hide('hud'); hide('centerHud'); hide('controls'); updateTouchUI();
  document.getElementById('rewardLine').innerHTML="";
  const qLines=[];   // quest/growth notifications for the reward panel

  if(won){
    arena.tokensThisRun++; save.tokens++;              // 1 token per round survived
    save.totalArenaWins=(save.totalArenaWins||0)+1;     // drives the shop's 5-win rotation
    arena.round++;
    if(arena.round>save.arenaBest) save.arenaBest=arena.round;
    // Growth + quest progress for surviving this round (KOs this round, arena metric, tiny win credit)
    const up=awardGrowth(chosen, 0, defeated);
    if(up){ const lootTxt = up.loot&&up.loot.length ? ` — ${up.loot.join(' ')}` : '';
      qLines.push(`<span style="color:#8fd3a8;font-weight:bold;">🌿 ${CHARS[chosen].name} grew to ${up.tier}!${lootTxt}</span>`); }
    const comp=[]; questAdvance('arena',1,{char:chosen}).forEach(q=>comp.push(q)); if(defeated>0) questAdvance('ko',defeated,{char:chosen}).forEach(q=>comp.push(q));
    if(matchDamage>0){ questAdvance('dmg',Math.round(matchDamage),{char:chosen}).forEach(q=>comp.push(q)); matchDamage=0; }   // damage quests also progress in Silverdome; reset the tally each round
    comp.forEach(q=>{ const got=grantQuestReward(q); qLines.push(`<span style="color:#ffcf6b;font-weight:bold;">✅ Quest: ${q.text}${got?` — ${got}`:''}</span>`); });
    { const normalDone=comp.filter(q=>!(QUEST_BY_ID[q.id]&&QUEST_BY_ID[q.id].mega)).length; if(creditQuestsDone(normalDone)) qLines.push(`<span style="color:#ffd6ff;font-weight:bold;">✦ MEGA-QUEST unlocked! Complete it to earn a Mythic Masters pack!</span>`); }
    save.quests=save.quests.filter(s=>!s.done); ensureQuests();
    persistSave();
    if(arena.round>=ARENA_ROUNDS){
      // cleared the whole gauntlet — counts as a full WIN for growth, and marks this brawler a Silverdome Champion
      const winUp=awardGrowth(chosen, GROWTH_PLACEMENT[1], 0);
      if(winUp){ const lt = winUp.loot&&winUp.loot.length ? ` — ${winUp.loot.join(' ')}` : '';
        qLines.push(`<span style="color:#8fd3a8;font-weight:bold;">🌿 ${CHARS[chosen].name} grew to ${winUp.tier}!${lt}</span>`); }
      const firstClear = !(save.silverdomeDone && save.silverdomeDone[chosen]);
      if(!save.silverdomeDone) save.silverdomeDone={};
      save.silverdomeDone[chosen]=true; persistSave();
      if(firstClear) qLines.push(`<span style="color:#dfe6ef;font-weight:bold;">🏛 ${CHARS[chosen].name} is now a Silverdome Champion!</span>`);
      t.textContent="SILVERDOME CHAMPION!"; t.style.color="#dfe6ef";
      document.getElementById('overText').textContent=
        `You cleared all ${ARENA_ROUNDS} rounds! Counts as a win — +${arena.tokensThisRun} Silver Tokens this run.`;
      document.getElementById('rewardLine').innerHTML = qLines.join('<br>');
      arena.active=false;
      nextBtn.classList.add('hidden');
      againBtn.textContent="RUN IT AGAIN";
    } else {
      t.textContent=`ROUND ${arena.round} CLEARED`; t.style.color="#8fd3a8";
      const nextMod = "Next up: a fresh modifier awaits.";
      document.getElementById('overText').textContent=
        `+1 Silver Token (${save.tokens} total). ${nextMod}`;
      nextBtn.textContent=`ROUND ${arena.round+1} →`;
      nextBtn.classList.remove('hidden');
      againBtn.textContent="RESTART RUN";
    }
    sfx('unlock');
  } else {
    // lost: the run ends, but you keep the tokens you banked
    t.textContent="ELIMINATED"; t.style.color="#e04b3a";
    document.getElementById('overText').textContent=
      `Knocked out on round ${arena.round+1}. You banked ${arena.tokensThisRun} Silver Token${arena.tokensThisRun===1?'':'s'} this run (${save.tokens} total).`;
    arena.active=false;
    nextBtn.classList.add('hidden');
    againBtn.textContent="NEW RUN";
    sfx('super');
  }
  document.getElementById('rewardLine').innerHTML=
    `🎟 ${save.tokens} Silver Tokens  ·  best run: round ${save.arenaBest}` + qLines.map(l=>`<br>${l}`).join('');
  shopBtn.classList.remove('hidden');   // let players spend tokens between runs
  const ov=document.getElementById('overScreen'); ov.classList.add('fade-in'); ov.classList.remove('hidden');
}

/* ---------- Screen helpers ---------- */
function show(id){document.getElementById(id).classList.remove('hidden'); syncBgScene(); if(id==='titleScreen') refreshModeLocks();}
function hide(id){document.getElementById(id).classList.add('hidden'); syncBgScene();}
// paint the lock state onto the gated mode buttons: locked → 🔒 + trophies needed, dimmed
function refreshModeLocks(){
  let anyUnlocked=false;
  MODE_UNLOCKS.forEach(m=>{
    const b=document.getElementById(m.btn); if(!b) return;
    const unlocked=isModeUnlocked(m.id);
    // locked modes are hidden entirely until the player crosses their lifetime-trophy threshold
    b.style.display = unlocked ? '' : 'none';
    if(unlocked) anyUnlocked=true;
  });
  // hide the whole "MORE MODES" group until at least one unlockable mode is available
  const grp=document.getElementById('moreModesGroup');
  if(grp) grp.style.display = anyUnlocked ? '' : 'none';
  paintModeStrips();
}
// paint each mode card's bottom strip: a themed, repeated motif drawn in the card's --acc accent color
function paintModeStrips(){
  document.querySelectorAll('.btn.mode .mStrip').forEach(cv=>{
    const g=cv.getContext&&cv.getContext('2d'); if(!g) return;
    const W=cv.width, H=cv.height;
    // read the accent straight off the button's inline style (most reliable), fall back to computed, then amber
    const card=cv.closest('.btn.mode');
    let acc=(card&&card.style.getPropertyValue('--acc').trim()) || getComputedStyle(cv.parentElement).getPropertyValue('--acc').trim() || '#e69a00';
    g.clearRect(0,0,W,H);
    // tinted base band (accent → darker accent) so the strip reads as a colored footer
    const bg=g.createLinearGradient(0,0,0,H); bg.addColorStop(0,acc); bg.addColorStop(1,shadeHex(acc,-46));
    g.fillStyle=bg; g.fillRect(0,0,W,H);
    g.save(); g.globalAlpha=0.9; g.strokeStyle="rgba(255,255,255,.85)"; g.fillStyle="rgba(255,255,255,.85)"; g.lineWidth=1.4; g.lineCap="round";
    const motif=cv.dataset.motif, cy=H/2, step=26, r=3.2;
    for(let x=step/2; x<W; x+=step){
      g.beginPath();
      switch(motif){
        case 'ffa':      // crossed-swords X marks
          g.moveTo(x-r,cy-r); g.lineTo(x+r,cy+r); g.moveTo(x+r,cy-r); g.lineTo(x-r,cy+r); g.stroke(); break;
        case 'tutorial': // 4-point sparkles
          g.moveTo(x,cy-r); g.lineTo(x,cy+r); g.moveTo(x-r,cy); g.lineTo(x+r,cy); g.stroke(); break;
        case 'practice': // target rings
          g.arc(x,cy,r,0,6.28); g.stroke(); g.beginPath(); g.arc(x,cy,r*0.4,0,6.28); g.fill(); break;
        case 'relay':    // flame tongues
          g.moveTo(x,cy+r); g.quadraticCurveTo(x-r,cy,x,cy-r); g.quadraticCurveTo(x+r,cy,x,cy+r); g.fill(); break;
        case 'arena':    // 5-point stars
          for(let k=0;k<10;k++){ const a=-1.57+k*Math.PI/5, rr=(k%2?r*0.45:r), px=x+Math.cos(a)*rr, py=cy+Math.sin(a)*rr; k?g.lineTo(px,py):g.moveTo(px,py); } g.closePath(); g.fill(); break;
        case 'pearl':    // bubbles (ring + highlight)
          g.arc(x,cy,r,0,6.28); g.stroke(); g.beginPath(); g.arc(x-r*0.35,cy-r*0.35,r*0.28,0,6.28); g.fill(); break;
        case 'payload':  // rail-track dashes
          g.moveTo(x-r*1.4,cy); g.lineTo(x+r*1.4,cy); g.stroke(); g.beginPath(); g.moveTo(x,cy-r*0.7); g.lineTo(x,cy+r*0.7); g.stroke(); break;
        case 'ctf':      // acorns (nut + cap)
          g.ellipse(x,cy+r*0.3,r*0.7,r*0.9,0,0,6.28); g.fill(); g.beginPath(); g.ellipse(x,cy-r*0.4,r*0.8,r*0.4,0,0,6.28); g.fill(); break;
        case 'whiteout': // little UFO domes / stars alternating
          if((x/step|0)%2){ g.arc(x,cy,r*0.55,0,6.28); g.fill(); }
          else { g.ellipse(x,cy+r*0.2,r,r*0.4,0,0,6.28); g.fill(); g.beginPath(); g.arc(x,cy-r*0.2,r*0.45,Math.PI,0); g.fill(); } break;
        case 'binas':    // atoms: a nucleus dot with a little orbit ring
          g.arc(x,cy,r*0.4,0,6.28); g.fill(); g.beginPath(); g.ellipse(x,cy,r*1.1,r*0.5,0.6,0,6.28); g.stroke(); break;
        default: g.arc(x,cy,r*0.5,0,6.28); g.fill();
      }
    }
    g.restore();
  });
}
// lighten/darken a #rrggbb hex by amt (−255..255) → rgb() string
function shadeHex(hex, amt){
  hex=hex.replace('#',''); if(hex.length===3) hex=hex.split('').map(c=>c+c).join('');
  let r=clamp(parseInt(hex.slice(0,2),16)+amt,0,255), gg=clamp(parseInt(hex.slice(2,4),16)+amt,0,255), b=clamp(parseInt(hex.slice(4,6),16)+amt,0,255);
  return `rgb(${r|0},${gg|0},${b|0})`;
}
// the painted background scene is visible only while a menu screen is up (hidden during gameplay)
function syncBgScene(){
  const scn=document.getElementById('bgScene'); if(!scn) return;
  const anyScreen=[...document.querySelectorAll('.screen')].some(s=>!s.classList.contains('hidden'));
  scn.classList.toggle('hidden', !anyScreen);
}
// reset the over-screen buttons to their non-arena default (FFA / relay)
function resetOverButtons(){
  document.getElementById('nextRoundBtn').classList.add('hidden');
  document.getElementById('shopFromOver').classList.add('hidden');
  document.getElementById('againBtn').textContent="PLAY AGAIN";
}
/* ---------- Build character cards ---------- */
// stat-bar scaling references (max HP / speed across the roster; dummy excluded)
const MAX_HP = Math.max(...ALL_CHAR_IDS.map(k=>CHARS[k].maxHp));
const MAX_SPD = Math.max(...ALL_CHAR_IDS.map(k=>CHARS[k].speed));
// sustained damage-per-second for the preview bar: dmg × hits-per-shot × shots-per-second.
// accounts for reload (cd) and multi-hit attacks; a few specials get a hand-tuned rate.
const HITS_PER_SHOT = { josh:3, robin:2, adam:3 };   // attacks that land multiple projectiles
function dpsOf(key){
  const c=CHARS[key], atk=c.atk;
  if(key==='deniz'){
    // hold-to-spin: ~1 tick per cd, but ammo-limited. Approx: dmg per tick × ticks/sec, damped for reloads.
    const perSec = atk.dmg * (60/atk.cd) * 0.55;
    return perSec;
  }
  const hits = HITS_PER_SHOT[key] || 1;
  const shotsPerSec = 60 / (atk.cd || 60);
  return atk.dmg * hits * shotsPerSec;
}
const MAX_DPS = Math.max(...ALL_CHAR_IDS.map(dpsOf));
let selectFilter="all", selectSort="default";   // character-select role filter + sort key
function buildCards(){
  const list=document.getElementById('brawlerList'); list.innerHTML="";
  chosen=null;
  document.getElementById('previewEmpty').classList.remove('hidden');
  document.getElementById('previewCard').classList.add('hidden');
  // apply the active role filter, then the chosen sort order
  let items=Object.entries(CHARS).filter(([key,c])=> key!=='dummy' && key!=='spore' && (selectFilter==="all" || c.role===selectFilter));
  const nameOf=([k,c])=>c.name.toLowerCase();
  const usesOf=(k)=>((save.stats&&save.stats.byChar&&save.stats.byChar[k]&&save.stats.byChar[k].matches)||0);
  const cmp={
    default:  null,
    name:     (a,b)=> nameOf(a)<nameOf(b)?-1:1,
    hp:       (a,b)=> b[1].maxHp-a[1].maxHp,
    dps:      (a,b)=> dpsOf(b[0])-dpsOf(a[0]),
    spd:      (a,b)=> b[1].speed-a[1].speed,
    owned:    (a,b)=> (isUnlocked(b[0])?1:0)-(isUnlocked(a[0])?1:0),
    uses:     (a,b)=> usesOf(b[0])-usesOf(a[0]),   // most-played brawlers first
  }[selectSort];
  if(cmp) items.sort(cmp);
  items.forEach(([key,c])=>{
    const owned=isUnlocked(key);
    const node=TROPHY_ROAD.find(n=>n.type==='char'&&n.id===key);
    const need=node?node.cost+' 🏆':'locked';
    const row=document.createElement('div'); row.className='brow'+(owned?'':' locked'); row.dataset.key=key;
    const gt=growthTier(growthOf(key));
    const growthTag = owned ? `<div class="lockTag" title="Growth" style="color:${gt.color};">${gt.icon} ${gt.name}</div>` : `<div class="lockTag">🔒 ${need}</div>`;
    const champ = owned && save.silverdomeDone && save.silverdomeDone[key]
      ? `<div class="lockTag" title="Cleared all Silverdome rounds with this brawler" style="color:#dfe6ef;">🏛 Silverdome Champion</div>` : ``;
    row.innerHTML=`<canvas width="88" height="88"></canvas>
      <div><div class="bn">${c.name}</div><div class="br">${c.role}</div></div>
      ${growthTag}${champ}`;
    if(owned) row.onclick=()=>selectBrawler(key,row);
    list.appendChild(row);
    try{ drawPortrait(row.querySelector('canvas'),key); }catch(err){ console.error("portrait error:",err); }
  });
  if(list.children.length===0){ list.innerHTML=`<div style="opacity:.7; font-size:13px; text-align:center; padding:20px;">No brawlers match this filter.</div>`; }
}
// fill the right-hand preview panel and arm the PLAY button
function selectBrawler(key,row){
  chosen=key;
  document.querySelectorAll('.brow').forEach(x=>x.classList.remove('sel'));
  if(row) row.classList.add('sel');
  const c=CHARS[key];
  document.getElementById('previewEmpty').classList.add('hidden');
  document.getElementById('previewCard').classList.remove('hidden');
  document.getElementById('previewName').textContent=c.name;
  document.getElementById('previewRole').textContent=c.role;
  { const gp=growthProgress(key), rEl=document.getElementById('previewRole');
    const champ = save.silverdomeDone && save.silverdomeDone[key] ? ` &nbsp;·&nbsp; <span style="color:#dfe6ef;" title="Cleared all Silverdome rounds">🏛 Silverdome Champion</span>` : ``;
    rEl.innerHTML=`${c.role} &nbsp;·&nbsp; <span style="color:${gp.tier.color}">${gp.tier.icon} ${gp.tier.name}</span>`
      + (gp.next?` <span style="opacity:.6;">(${Math.floor(gp.cur)}/${gp.need} to ${gp.next.name})</span>`:` <span style="opacity:.6;">(max)</span>`) + champ; }
  document.getElementById('pvHp').style.width=Math.round(c.maxHp/MAX_HP*100)+'%';
  document.getElementById('pvDps').style.width=Math.round(dpsOf(key)/MAX_DPS*100)+'%';
  document.getElementById('pvSpd').style.width=Math.round(c.speed/MAX_SPD*100)+'%';
  document.getElementById('pvAtkName').textContent=c.atk.name;
  document.getElementById('pvAtkDesc').textContent=c.atk.desc;
  document.getElementById('pvSupName').textContent=c.sup.name;
  document.getElementById('pvSupDesc').textContent=c.sup.desc;
  try{ drawPortrait(document.getElementById('previewArt'),key); }catch(err){ console.error("preview error:",err); }
  renderPreviewCustom(key);
  sfx('ui');
}
// skins + emotes the player can equip for the selected brawler, shown in the preview panel
function renderPreviewCustom(key){
  const skinBox=document.getElementById('pvSkins'), emBox=document.getElementById('pvEmotes');
  if(!skinBox||!emBox) return;
  // --- skins: default look + every owned cosmetic for this brawler ---
  const skins=save.cosmetics.filter(id=>COSMETICS[id] && !COSMETICS[id].archived && COSMETICS[id].char===key).sort((a,b)=>rarityRank(a)-rarityRank(b));
  let sh=`<div class="pvcLbl">SKIN</div><div class="pvcChips">`;
  const defOn = !save.equipped[key];
  sh+=`<button class="pvcChip${defOn?' on':''}" data-skin="__default"><span class="sw" style="background:${CHARS[key].color}"></span>Default</button>`;
  skins.forEach(id=>{
    const co=COSMETICS[id], on=save.equipped[key]===id;
    const star = rarityStar(co.rarity);
    sh+=`<button class="pvcChip${on?' on':''}" data-skin="${id}"><span class="sw" style="background:${co.color}"></span>${star}${co.name}</button>`;
  });
  sh+=`</div>`;
  skinBox.innerHTML=sh;
  // --- emotes: none + every owned emote for this brawler ---
  const emotes=emotesForChar(key);
  let eh=`<div class="pvcLbl">EMOTE (press E / 💬 in-game)</div><div class="pvcChips">`;
  if(emotes.length===0){ eh+=`<span class="pvcEmpty">No emotes yet — win them in the 🎪 Shop.</span>`; }
  else {
    const cur=save.equippedEmote[key];
    emotes.forEach(id=>{ const on=cur===id;
      eh+=`<button class="pvcChip${on?' on':''}" data-emote="${id}">💬 “${EMOTES[id].text}”</button>`; });
  }
  eh+=`</div>`;
  emBox.innerHTML=eh;
  // wire skin chips
  skinBox.querySelectorAll('.pvcChip[data-skin]').forEach(btn=>{
    btn.onclick=()=>{
      const v=btn.dataset.skin;
      save.equipped[key] = (v==='__default') ? null : v;
      persistSave(); sfx('ui');
      drawPortrait(document.getElementById('previewArt'),key);
      renderPreviewCustom(key);
      // refresh the list portrait too
      const row=document.querySelector('.brow.sel canvas'); if(row){ try{ drawPortrait(row,key); }catch(e){} }
    };
  });
  // wire emote chips (toggle: click the equipped one to clear)
  emBox.querySelectorAll('.pvcChip[data-emote]').forEach(btn=>{
    btn.onclick=()=>{
      const id=btn.dataset.emote;
      save.equippedEmote[key] = (save.equippedEmote[key]===id) ? null : id;
      persistSave(); sfx('ui'); renderPreviewCustom(key);
    };
  });
}

/* static illustrated portrait for character cards */
function drawPortrait(cv2,key,cosmeticId){
  const c=CHARS[key]; const g=cv2.getContext('2d');
  const W2=cv2.width,H2=cv2.height, R=Math.round(Math.min(W2,H2)*0.386);   // scale sprite to the canvas (88px→34)
  g.clearRect(0,0,W2,H2);
  g.save(); g.translate(W2/2,H2*0.62);
  // color/gear/morph: explicit cosmetic > equipped > default
  let body, gear=null, morph=null;
  if(cosmeticId && COSMETICS[cosmeticId]){ body=COSMETICS[cosmeticId].color; gear=COSMETICS[cosmeticId].gear||null; morph=COSMETICS[cosmeticId].morph||null; }
  else if(isUnlocked(key)){ body=charColor(key); gear=charGear(key); morph=charMorph(key); }
  else { body=c.color; }
  const dark=shade(body,-40), light=shade(body,45);
  // custom art-pass brawlers: draw their own sprite (same code as in-game), then rare-skin extras
  if(CUSTOM_DRAW[key]){
    const pe={char:key, skinMorph:morph};   // pass the morph so morph-gated sprite branches (e.g. Sonia's axe) render in previews
    if(morph) drawMorph(g,morph,R,pe,'back');
    CUSTOM_DRAW[key](g, pe, R, body, dark, light);
    if(morph) drawMorph(g,morph,R,pe,'front');
    if(gear) drawSkinGear(g,gear,R,pe);
    g.restore();
    return;
  }
  const bd=buildOf(key);
  const bw=R*0.92*bd.bw, bh=R*1.02*bd.bh;
  const legX = bd.legs==='wide'?0.62 : bd.legs==='narrow'?0.34 : 0.5;
  const headR=R*bd.head, headY=-bh*0.95;
  // legs
  g.fillStyle=dark;
  g.beginPath(); g.roundRect(-R*legX,bh*0.55,R*0.4,R*0.5,4); g.fill();
  g.beginPath(); g.roundRect(R*(legX-0.4),bh*0.55,R*0.4,R*0.5,4); g.fill();
  // torso
  g.fillStyle=body; drawTorso(g, bd.torso, bw, bh);
  g.fillStyle=light; g.beginPath(); g.ellipse(-bw*0.28,-bh*0.15,bw*0.42,bh*0.55,0,0,6.28); g.fill();
  // base gear
  drawGearStatic(g,key,R,body,dark,light);
  // rare-skin sprite override
  if(morph){ drawMorph(g,morph,R,{char:key},'back'); drawMorph(g,morph,R,{char:key},'front'); }
  if(gear) drawSkinGear(g,gear,R,{char:key});
  // head
  g.fillStyle=light; g.beginPath(); g.arc(R*0.1,headY,headR,0,6.28); g.fill();
  drawEyes(g, bd.eyes, R*0.1, headY, headR);
  g.restore();
}
function drawGearStatic(g,key,R,body,dark,light){
  if(key==="nathan"){
    g.fillStyle=dark; g.beginPath(); g.arc(R*0.1,-R*1.25,R*0.6,Math.PI,0); g.fill();
    g.fillRect(R*0.1-R*0.6,-R*1.28,R*1.2,R*0.15);
    g.fillStyle=shade(dark,-15); g.beginPath(); g.ellipse(R*0.55,-R*1.2,R*0.5,R*0.16,0,0,Math.PI); g.fill();
    g.fillStyle="#fff"; g.beginPath(); g.arc(R*0.95,R*0.1,R*0.28,0,6.28); g.fill();
    g.strokeStyle="#e04b3a"; g.lineWidth=1.5; g.beginPath(); g.arc(R*0.85,R*0.1,R*0.28,-0.6,0.6); g.stroke();
  } else if(key==="daniel"){
    g.fillStyle=dark; g.beginPath(); g.ellipse(R*0.1,-R*1.15,R*0.75,R*0.2,0,0,6.28); g.fill();
    g.beginPath(); g.arc(R*0.1,-R*1.25,R*0.42,Math.PI,0); g.fill();
    g.fillStyle="#111"; g.beginPath(); g.arc(R*0.9,R*0.15,R*0.26,0,6.28); g.fill();
    g.fillStyle="#ff7043"; g.beginPath(); g.arc(R*0.9,-R*0.1,2.5,0,6.28); g.fill();
  } else if(key==="yassin"){
    g.fillStyle="#c0392b"; g.fillRect(R*0.1-R*0.62,-R*1.15,R*1.24,R*0.22);
    g.beginPath(); g.moveTo(R*0.1-R*0.62,-R*1.05); g.lineTo(R*0.1-R*0.95,-R*0.7); g.lineTo(R*0.1-R*0.75,-R*0.65); g.closePath(); g.fill();
    g.fillStyle="#c0392b"; g.beginPath(); g.arc(R*0.95,R*0.15,R*0.36,0,6.28); g.fill();
    g.fillStyle="#c0392b"; g.beginPath(); g.arc(-R*0.95,R*0.25,R*0.3,0,6.28); g.fill();
  } else if(key==="josh"){
    g.fillStyle=dark; g.beginPath(); g.arc(R*0.1,-R*1.15,R*0.55,Math.PI*1.05,Math.PI*1.95); g.fill();
    g.fillStyle=shade(dark,25); g.beginPath(); g.moveTo(R*0.6,-R*1.25); g.lineTo(R*0.95,-R*1.05); g.lineTo(R*0.55,-R*0.95); g.closePath(); g.fill();
    g.fillStyle="#8a8172"; g.beginPath(); g.arc(R*0.95,R*0.1,R*0.22,0,6.28); g.fill();
  } else if(key==="lars"){
    g.fillStyle="#ffd1e8"; for(let k=-1;k<=1;k++){ g.beginPath(); g.arc(R*0.1+k*R*0.35,-R*1.35,R*0.12,0,6.28); g.fill(); }
    g.fillStyle="#f27bb8"; const s=R*0.28, hx=R*0.95, hy=R*0.12;
    g.beginPath(); g.moveTo(hx,hy+s*0.6); g.bezierCurveTo(hx+s,hy-s*0.3,hx+s*0.5,hy-s,hx,hy-s*0.35);
    g.bezierCurveTo(hx-s*0.5,hy-s,hx-s,hy-s*0.3,hx,hy+s*0.6); g.fill();
  } else if(key==="milo"){
    g.fillStyle="#2a2a2a"; g.fillRect(R*0.1-R*0.6,-R*1.08,R*1.2,R*0.18);
    g.fillStyle="#7fd3ff"; g.fillRect(R*0.1-R*0.5,-R*1.05,R*1.0,R*0.09);
    g.strokeStyle="#f6c445"; g.lineWidth=3; g.beginPath(); g.moveTo(R*0.7,R*0.1); g.lineTo(R*1.25,R*0.1); g.stroke();
  } else if(key==="deniz"){
    g.fillStyle="#bfe9ff";
    for(let k=-1;k<=1;k++){ g.beginPath(); g.moveTo(R*0.1+k*R*0.32,-R*1.5); g.lineTo(R*0.1+k*R*0.32-4,-R*1.2); g.lineTo(R*0.1+k*R*0.32+4,-R*1.2); g.closePath(); g.fill(); }
    g.fillStyle="#8fd8f0"; g.beginPath(); g.arc(R*0.95,R*0.12,R*0.24,0,6.28); g.fill();
    g.beginPath(); g.arc(-R*0.95,R*0.2,R*0.2,0,6.28); g.fill();
  } else if(key==="fionn"){
    g.fillStyle=dark; g.beginPath(); g.arc(R*0.1,-R*1.1,R*0.6,Math.PI,0); g.fill();
    g.fillStyle=shade(dark,-10); g.beginPath(); g.moveTo(R*0.1-R*0.6,-R*1.1); g.lineTo(R*0.1,-R*0.55); g.lineTo(R*0.1+R*0.6,-R*1.1); g.closePath(); g.fill();
    g.strokeStyle="#dfe3ff"; g.lineWidth=4; g.beginPath(); g.moveTo(R*0.7,R*0.3); g.lineTo(R*1.5,-R*0.4); g.stroke();
  } else if(key==="reshman"){
    g.fillStyle="#e8a13a"; g.fillRect(R*0.1-R*0.6,-R*1.15,R*1.2,R*0.2);
    g.fillStyle=shade("#e8a13a",-20); g.beginPath(); g.arc(R*0.95,R*0.15,R*0.26,0,Math.PI); g.fill();
    g.fillStyle="#fff3d0"; g.beginPath(); g.ellipse(R*0.95,R*0.12,R*0.26,R*0.1,0,Math.PI,0); g.fill();
  } else if(key==="renas"){
    g.fillStyle=shade("#2fb3a6",30); g.beginPath(); g.moveTo(R*0.1,-R*1.5); g.lineTo(R*0.1-R*0.28,-R*1.15); g.lineTo(R*0.1+R*0.28,-R*1.15); g.closePath(); g.fill();
    g.strokeStyle="#2fb3a6"; g.lineWidth=5; g.lineJoin="round";
    g.beginPath(); g.moveTo(R*0.7,R*0.3); g.lineTo(R*1.05,R*0.0); g.lineTo(R*0.75,-R*0.25); g.stroke();
  } else if(key==="adam"){
    g.fillStyle="#e05a9c"; g.fillRect(R*0.1-R*0.6,-R*1.12,R*1.2,R*0.16);
    g.fillStyle=shade("#e05a9c",-25); g.beginPath(); g.ellipse(R*1.0,R*0.05,R*0.3,R*0.36,0.3,0,6.28); g.fill();
    g.strokeStyle="#7a4a2a"; g.lineWidth=4; g.beginPath(); g.moveTo(R*0.7,R*0.3); g.lineTo(R*0.9,R*0.1); g.stroke();
    g.fillStyle="#fff"; g.beginPath(); g.arc(R*0.55,-R*0.2,R*0.12,0,6.28); g.fill();
  } else if(key==="evadam"){
    g.fillStyle="#1a0a12"; g.beginPath();
    g.moveTo(-R*0.7,-R*1.2); g.lineTo(-R*0.5,-R*1.9); g.lineTo(R*0.1,-R*1.35);
    g.lineTo(R*0.7,-R*1.9); g.lineTo(R*0.9,-R*1.2); g.closePath(); g.fill();
    g.fillStyle="#c81f3a"; g.beginPath(); g.arc(R*0.1,-R*1.28,R*0.14,0,6.28); g.fill();
    g.fillStyle="#fff"; g.beginPath();
    g.moveTo(-R*0.1,-R*0.55); g.lineTo(-R*0.02,-R*0.55); g.lineTo(-R*0.06,-R*0.4); g.closePath(); g.fill();
    g.beginPath(); g.moveTo(R*0.16,-R*0.55); g.lineTo(R*0.24,-R*0.55); g.lineTo(R*0.2,-R*0.4); g.closePath(); g.fill();
  } else if(key==="otis"){
    g.fillStyle="#b9c2cf"; g.beginPath(); g.roundRect(-R*0.95,-R*0.9,R*0.34,R*1.1,5); g.fill();
    g.fillStyle="#ff8a3d"; g.fillRect(-R*0.95,-R*0.9,R*0.34,R*0.16);
    g.fillStyle=shade("#d8dde6",-25);
    g.beginPath(); g.ellipse(-R*0.55,-R*1.15,R*0.2,R*0.4,0.5,0,6.28); g.fill();
    g.beginPath(); g.ellipse(R*0.7,-R*1.15,R*0.2,R*0.4,-0.5,0,6.28); g.fill();
    g.fillStyle="rgba(180,220,255,.28)"; g.beginPath(); g.arc(R*0.1,-R*1.05,R*0.78,0,6.28); g.fill();
    g.strokeStyle="#e6ecf5"; g.lineWidth=3; g.beginPath(); g.arc(R*0.1,-R*1.05,R*0.78,0,6.28); g.stroke();
    g.strokeStyle="#ff8a3d"; g.lineWidth=4; g.beginPath(); g.arc(R*0.1,-R*1.05,R*0.78,Math.PI*0.15,Math.PI*0.6); g.stroke();
    g.fillStyle=shade("#d8dde6",-12); g.beginPath(); g.ellipse(R*0.35,-R*0.95,R*0.22,R*0.16,0,0,6.28); g.fill();
    g.fillStyle="#2a2320"; g.beginPath(); g.arc(R*0.5,-R*0.98,R*0.07,0,6.28); g.fill();
  } else if(key==="johan"){
    const bc=charColor('johan');
    g.fillStyle=shade(bc,-30); g.beginPath(); g.arc(R*0.1,-R*1.2,R*0.52,Math.PI,0); g.fill();
    g.fillStyle=shade(bc,-45); g.beginPath(); g.ellipse(R*0.5,-R*1.18,R*0.42,R*0.13,0,0,Math.PI); g.fill();
    g.fillStyle="#f4d03f"; g.beginPath(); g.arc(-R*0.9,R*0.2,R*0.2,0,6.28); g.fill();
    g.fillStyle="#5bbf6a"; g.beginPath(); g.roundRect(R*0.8,-R*0.1,R*0.3,R*0.42,3); g.fill();
    g.fillStyle="#3a8f4a"; g.fillRect(R*0.84,-R*0.28,R*0.14,R*0.2);
    g.strokeStyle="#3a8f4a"; g.lineWidth=3; g.beginPath(); g.moveTo(R*0.98,-R*0.24); g.lineTo(R*1.2,-R*0.12); g.stroke();
  } else if(key==="robin"){
    g.fillStyle="#7fc8ff";
    g.beginPath(); g.moveTo(-R*0.06,-R*0.95); g.quadraticCurveTo(-R*0.16,-R*0.5,-R*0.1,-R*0.35); g.quadraticCurveTo(-R*0.02,-R*0.5,-R*0.06,-R*0.95); g.fill();
    g.beginPath(); g.moveTo(R*0.26,-R*0.95); g.quadraticCurveTo(R*0.16,-R*0.5,R*0.22,-R*0.35); g.quadraticCurveTo(R*0.3,-R*0.5,R*0.26,-R*0.95); g.fill();
    g.strokeStyle="#2e4a66"; g.lineWidth=2.5; g.beginPath(); g.arc(R*0.26,-R*1.02,R*0.16,0,6.28); g.stroke();
  }
}

/* ---------- Buttons ---------- */
document.getElementById('toSelect').onclick=()=>{ gameMode="ffa"; resetOverButtons(); hide('titleScreen'); show('selectScreen'); buildCards(); updateSelectShopBtn(); };
// gated mode entry: locked modes shake + announce their trophy requirement instead of starting
function enterMode(id, setup){
  if(!isModeUnlocked(id)){ sfx('ui'); const need=modeNeed(id); banner(`🔒 ${Math.max(0,need-(save.lifetimePoints||0))} more lifetime trophies`, "super"); return; }
  if(setup) setup();
  resetOverButtons(); hide('titleScreen'); show('selectScreen'); buildCards(); updateSelectShopBtn();
}
document.getElementById('toRelay').onclick=()=>enterMode('relay',()=>gameMode="relay");
document.getElementById('toPearl').onclick=()=>enterMode('pearl',()=>gameMode="pearl");
document.getElementById('toPayload').onclick=()=>enterMode('payload',()=>gameMode="payload");
document.getElementById('toCtf').onclick=()=>enterMode('ctf',()=>gameMode="ctf");
document.getElementById('toWhiteout').onclick=()=>enterMode('whiteout',()=>gameMode="whiteout");
document.getElementById('toBinas').onclick=()=>enterMode('binas',()=>gameMode="binas");
document.getElementById('toPractice').onclick=()=>{ gameMode="practice"; resetOverButtons(); hide('titleScreen'); show('selectScreen'); buildCards(); updateSelectShopBtn(); };
document.getElementById('prMove').onclick=()=>{ practice.moving=!practice.moving; sfx('ui'); updatePracticeUI(); };
document.getElementById('prShoot').onclick=()=>{ practice.shootBack=!practice.shootBack; sfx('ui'); updatePracticeUI(); };
document.getElementById('prReset').onclick=()=>{ sfx('ui'); resetPracticeDummies(); };
document.getElementById('prExit').onclick=()=>{ sfx('ui'); document.getElementById('practiceBar').classList.add('hidden'); state="title"; hide('hud'); hide('centerHud'); hide('controls'); stopMusic(); show('titleScreen'); };
// --- Tutorial wiring: launch helper, skip button, repeat button ---
function launchTutorial(){
  sfx('ui');
  // the tutorial always runs with a starter brawler so a brand-new player has something to control
  chosen = (save.unlocked && save.unlocked[0]) || STARTER_CHARS[0] || ALL_CHAR_IDS[0];
  gameMode="tutorial";
  hide('titleScreen'); hide('selectScreen'); hide('overScreen');
  startMatch();
}
document.getElementById('tutSkip').onclick=()=>{ sfx('ui'); tutorialAdvance(); };
{ const tb=document.getElementById('toTutorial'); if(tb) tb.onclick=()=>launchTutorial(); }
document.getElementById('toArena').onclick=()=>enterMode('arena',()=>{ gameMode="arena"; arena.round=0; arena.tokensThisRun=0; });
document.getElementById('shopBack').onclick=()=>{ sfx('ui'); closeShop(); };
document.getElementById('selectShop').onclick=()=>{ sfx('ui'); openShop('selectScreen'); };
document.getElementById('spinBtn').onclick=()=>{ initAudio(); spinRoulette(); };
// the shop is reachable from the arena's character-select only (plus the round result screens)
function updateSelectShopBtn(){
  document.getElementById('selectShop').classList.toggle('hidden', gameMode!=="arena");
}
// PROGRESS & EXTRAS: one toggle reveals/hides the panel of sub-menus, keeping the title screen tidy
document.getElementById('progressToggle').onclick=()=>{
  sfx('ui');
  const panel=document.getElementById('progressPanel'), btn=document.getElementById('progressToggle');
  const open=panel.classList.toggle('hidden')===false;
  btn.setAttribute('aria-expanded', open?'true':'false');
  btn.textContent = open ? "☰ PROGRESS & EXTRAS ▴" : "☰ PROGRESS & EXTRAS ▾";
};
document.getElementById('toRoad').onclick=()=>{ hide('titleScreen'); show('roadScreen'); renderRoad(); };
document.getElementById('roadBack').onclick=()=>{ hide('roadScreen'); show('titleScreen'); };
