// ---- Skin Gallery: browse & inspect every skin (view-only) ----
let galleryFilter='all';
const GALLERY_FILTERS = [
  {id:'all',    label:'All'},
  {id:'common', label:'🍀 Common', test:c=>c.rarity==='common'},
  {id:'rare',   label:'★ Rare',    test:c=>c.rarity==='rare'},
  {id:'silver', label:'❖ Silverdome', test:c=>c.rarity==='silver'},
  {id:'mythic', label:'✦ Mythic',  test:c=>c.rarity==='mythic'},
  {id:'playtime',label:'✦ Playtime', test:c=>c.pack==='playtime'},
  {id:'nature',  label:'🌿 Nature',  test:c=>c.pack==='nature'},
  {id:'space',   label:'🌌 Space',   test:c=>c.pack==='space'}
];
function renderGallery(){
  // how many cosmetics the player owns within a given filter (drives the "???" hiding of whole sets)
  const filterOwned=f=>ALL_COSMETIC_IDS.filter(id=>{ const c=COSMETICS[id]; return (f.test?f.test(c):true) && ownsCosmetic(id); }).length;
  // filter chips — a set you own NOTHING from shows as "???" so its very theme stays a surprise
  const fb=document.getElementById('galleryFilters'); fb.innerHTML='';
  GALLERY_FILTERS.forEach(f=>{
    const discovered = f.id==='all' || filterOwned(f)>0;
    const b=document.createElement('button'); b.className='glFilt'+(galleryFilter===f.id?' on':'');
    b.textContent = discovered ? f.label : '❔ ???';
    b.onclick=()=>{ galleryFilter=f.id; sfx('ui'); renderGallery(); };
    fb.appendChild(b);
  });
  // grid: owned skins shown fully; everything else a locked "???" slot (grouped by character then rarity)
  const grid=document.getElementById('galleryGrid'); grid.innerHTML='';
  const filt=GALLERY_FILTERS.find(f=>f.id===galleryFilter);
  const ids=ALL_COSMETIC_IDS.filter(id=>{ const c=COSMETICS[id]; return filt.test?filt.test(c):true; })
    .sort((a,b)=>{ const ca=CHARS[COSMETICS[a].char].name, cb=CHARS[COSMETICS[b].char].name; if(ca!==cb) return ca<cb?-1:1; return rarityRank(a)-rarityRank(b); });
  // a small "collected" tally at the top of the grid
  const owned=ids.filter(id=>ownsCosmetic(id)).length;
  const tally=document.createElement('div'); tally.style.cssText='width:100%; text-align:center; font-size:13px; opacity:.7; margin-bottom:6px;';
  tally.textContent=`Collected ${owned} / ${ids.length}`;
  grid.appendChild(tally);
  ids.forEach(id=>{
    const co=COSMETICS[id];
    if(ownsCosmetic(id)){
      const cell=document.createElement('div'); cell.className='glCell';
      cell.innerHTML=`<span class="glDot" style="color:${RARITY_COLOR[co.rarity]||'#8fd3a8'}; background:${RARITY_COLOR[co.rarity]||'#8fd3a8'}"></span>
        <canvas width="120" height="120"></canvas>
        <div class="glName">${rarityStar(co.rarity)}${co.name}</div>
        <div class="glChar">${CHARS[co.char].emoji} ${CHARS[co.char].name}</div>`;
      cell.onclick=()=>openSkinPeek(id);
      grid.appendChild(cell);
      try{ drawPortrait(cell.querySelector('canvas'), co.char, id); }catch(e){}
    } else {
      // locked: no portrait, no name — just a "???" teaser so the surprise is preserved
      const cell=document.createElement('div'); cell.className='glCell glLocked';
      cell.innerHTML=`<div class="glQ">?</div><div class="glName" style="opacity:.4;">???</div><div class="glChar" style="opacity:.4;">locked</div>`;
      grid.appendChild(cell);
    }
  });
}
