/* ---------- Options / phone mode ---------- */
function updateTouchToggleUI(){
  const b=document.getElementById('touchToggle'); if(!b) return;
  const label = save.touchMode===null ? 'AUTO'+(DEVICE_HAS_TOUCH?' (on)':' (off)') : (save.touchMode?'ON':'OFF');
  b.textContent='Phone mode: '+label;
}
document.getElementById('optionsBtn').onclick=()=>{ sfx('ui'); hide('titleScreen'); hide('selectScreen'); hide('roadScreen'); hide('overScreen'); show('optionsScreen'); updateTouchToggleUI(); };
document.getElementById('optionsBack').onclick=()=>{ sfx('ui'); hide('optionsScreen'); show('titleScreen'); };
document.getElementById('touchToggle').onclick=()=>{
  // cycle AUTO -> ON -> OFF -> AUTO
  save.touchMode = save.touchMode===null ? true : (save.touchMode===true ? false : null);
  persistSave(); updateTouchToggleUI(); updateTouchUI(); sfx('ui');
};
// show/hide the on-screen sticks depending on state + whether we're playing
function updateTouchUI(){
  const el=document.getElementById('touchUI'); if(!el) return;
  const ton=touchActive();
  document.body.classList.toggle('touch', ton);   // switch to the full-screen phone layout
  const on = state==="play" && ton;
  if(on) el.classList.remove('hidden'); else el.classList.add('hidden');
  // the keyboard-controls hint is meaningless on touch — hide it there
  const ctrls=document.getElementById('controls');
  if(ctrls && ton) ctrls.classList.add('hidden');
}

/* ---------- Touch stick handling ---------- */
// true when the play frame is CSS-rotated 90° cw (touch mode + portrait screen)
function frameRotated(){ return document.body.classList.contains('touch') && window.matchMedia('(orientation: portrait)').matches; }
function bindStick(elId, onVec, onEnd){
  const el=document.getElementById(elId); if(!el) return;
  let active=-1;   // pointerId currently controlling this stick
  const nub=el.querySelector('.tnub');
  const update=(e)=>{
    const r=el.getBoundingClientRect();
    const cx=r.left+r.width/2, cy=r.top+r.height/2, rad=r.width/2;
    let sx=e.clientX-cx, sy=e.clientY-cy;
    // if the frame is rotated 90° cw, convert the screen delta into game-space delta
    let dx=sx, dy=sy;
    if(frameRotated()){ dx=sy; dy=-sx; }
    const m=Math.hypot(dx,dy)||1; const clampM=Math.min(m,rad);
    const nx=dx/m, ny=dy/m;
    // the nub moves in SCREEN space (it lives inside the rotated frame), so use the raw screen delta
    const sm=Math.hypot(sx,sy)||1, snx=sx/sm, sny=sy/sm, sc=Math.min(sm,rad);
    if(nub) nub.style.transform=`translate(calc(-50% + ${snx*sc}px), calc(-50% + ${sny*sc}px))`;
    onVec(nx, ny, clampM/rad);   // unit dir (game space) + magnitude 0..1
  };
  el.addEventListener('pointerdown',e=>{ e.preventDefault(); active=e.pointerId; el.setPointerCapture(e.pointerId); initAudio(); update(e); });
  el.addEventListener('pointermove',e=>{ if(e.pointerId!==active)return; e.preventDefault(); update(e); });
  const release=e=>{ if(e.pointerId!==active)return; active=-1; if(nub) nub.style.transform='translate(-50%,-50%)'; onEnd(); };
  el.addEventListener('pointerup',release);
  el.addEventListener('pointercancel',release);
}
bindStick('moveStick', (nx,ny,mag)=>{ touch.moveX=nx*mag; touch.moveY=ny*mag; }, ()=>{ touch.moveX=0; touch.moveY=0; });
// FIRE button: hold to keep attacking (auto-aim handles direction)
(function(){
  const atk=document.getElementById('touchAttack'); if(!atk) return;
  let id=-1;
  atk.addEventListener('pointerdown',e=>{ e.preventDefault(); id=e.pointerId; atk.setPointerCapture(e.pointerId); initAudio(); touch.attacking=true; });
  const rel=e=>{ if(e.pointerId!==id)return; id=-1; touch.attacking=false; };
  atk.addEventListener('pointerup',rel);
  atk.addEventListener('pointercancel',rel);
})();
(function(){
  const sup=document.getElementById('touchSuper'); if(!sup) return;
  sup.addEventListener('pointerdown',e=>{ e.preventDefault(); initAudio(); touch.superTap=true; });
})();
(function(){
  const em=document.getElementById('touchEmote'); if(!em) return;
  em.addEventListener('pointerdown',e=>{ e.preventDefault(); initAudio(); if(state==='play') playerEmote('manual'); });
})();

/* ---------- Skin reveal flow ---------- */
let revealQueue=[], revealReturnScreen='overScreen', pendingPacks=[], koReelQueue=[], brawlerRevealQueue=[], growthSkinReveals=[];
function queueReveals(ids, returnScreen){
  if(!ids || !ids.length) return false;
  revealQueue=ids.slice(); revealReturnScreen=returnScreen||'overScreen';
  showNextReveal(); return true;
}
// show skin reveals AND any earned mega-quest packs, then return to `returnScreen`.
// when there is nothing to reveal, just show `returnScreen` directly so the caller never freezes.
// `charIds` (optional) = freshly-unlocked brawlers, revealed with the same card-flip FIRST.
function flushRewards(ids, returnScreen, charIds){
  const dest=returnScreen||'overScreen';
  brawlerRevealQueue=(charIds||[]).slice();
  // Growth-tier skins are a milestone → they get the CARD-FLIP suspense reveal (not the KO roulette reel).
  const growthSkins=growthSkinReveals.slice(); growthSkinReveals=[];
  // earned-by-playing skins (KO-points + quest rewards) roll on the ROULETTE reel; packs still open their own reel
  if((ids&&ids.length) || pendingPacks.length || brawlerRevealQueue.length || growthSkins.length){
    koReelQueue=(ids||[]).slice(); revealQueue=growthSkins; revealReturnScreen=dest;
    showNextReveal(); return true;
  }
  show(dest);
  if(dest==='shopScreen') renderShop();
  if(dest==='sanctuaryScreen') renderSanctuary();
  if(dest==='toyboxScreen') renderToybox();
  if(dest==='natureScreen') renderNature();
  if(dest==='schoolScreen') renderSchool();
  return false;
}
function showNextReveal(){
  // NEW BRAWLER unlocks flip first, on the same suspense card as skins
  if(brawlerRevealQueue.length){ showBrawlerReveal(); return; }
  if(revealQueue.length===0){
    if(pendingPacks.length){ const pk=pendingPacks.shift(); playPackRoulette(pk); return; }   // then open any earned skin packs
    if(koReelQueue.length){ const id=koReelQueue.shift(); playSkinRoulette(id, revealReturnScreen); return; }   // then roll any KO-points skins on the reel
    show(revealReturnScreen);
    if(revealReturnScreen==='shopScreen') renderShop();   // reflect the purchase when returning to the stall
    if(revealReturnScreen==='sanctuaryScreen') renderSanctuary();
    if(revealReturnScreen==='toyboxScreen') renderToybox();
    if(revealReturnScreen==='natureScreen') renderNature();
    if(revealReturnScreen==='schoolScreen') renderSchool();
    if(revealReturnScreen==='observatoryScreen') renderObservatory();
    return;
  }
  const id=revealQueue[0], co=COSMETICS[id];
  const scr=document.getElementById('revealScreen');
  const tier = co.rarity==='common' ? 'common' : (co.rarity==='silver' ? 'silver' : (co.rarity==='mythic'||co.rarity==='special') ? 'mythic' : 'rare');
  const label = co.rarity==='mythic' ? '✦ SPECIAL · MYTHIC ✦'
    : co.pack==='playtime' ? '✦ SPECIAL · PLAYTIME ✦'
    : co.pack==='nature' ? '✦ SPECIAL · NATURE ✦'
    : co.pack==='space' ? '✦ SPECIAL · SPACE ✦'
    : co.rarity==='special' ? '✦ SPECIAL ✦'
    : tier==='rare' ? '★ RARE SKIN ★'
    : tier==='silver' ? '❖ SILVERDOME SKIN ❖'
    : 'COMMON SKIN';
  // draw the art now (hidden under the card-back during suspense) so it's ready the instant we flip
  drawPortrait(document.getElementById('revealArt'), co.char, id);
  document.getElementById('revealRarity').textContent = label;
  document.getElementById('revealName').textContent=co.name;
  document.getElementById('revealChar').textContent='for '+CHARS[co.char].name;
  document.getElementById('revealEquip').textContent='EQUIP';
  document.getElementById('revealLater').textContent='LATER';
  const rarityCls = tier==='common'?' common':tier==='silver'?' silver':tier==='mythic'?' mythic':'';
  ['overScreen','roadScreen','titleScreen','shopScreen','sanctuaryScreen'].forEach(hide);
  // PHASE 1 — suspense: a face-down mystery card charges up (borrows the pack's anticipation)
  scr.className='screen'+rarityCls+' suspense';
  void scr.offsetWidth;   // restart the charge animation
  show('revealScreen');
  sfx('ui');
  // PHASE 2 — after the charge, snap to the real reveal (rays + card pop + sparks all fire on reflow)
  clearTimeout(showNextReveal._t);
  showNextReveal._t=setTimeout(()=>{
    if(document.getElementById('revealScreen').classList.contains('hidden')) return;
    scr.className='screen'+rarityCls;   // drop .suspense -> triggers revPop/revRaysIn/revSpark
    void scr.offsetWidth;
    sfx(tier==='common'?'ui':'unlock');
  }, 1800);
}
document.getElementById('revealEquip').onclick=()=>{
  if(brawlerRevealQueue.length){ const cid=brawlerRevealQueue.shift(); if(cid){ chosen=cid; } sfx('ui'); hide('revealScreen'); showNextReveal(); return; }
  const id=revealQueue.shift(); if(id){ save.equipped[COSMETICS[id].char]=id; persistSave(); }
  sfx('ui'); hide('revealScreen'); showNextReveal();
};
document.getElementById('revealLater').onclick=()=>{
  if(brawlerRevealQueue.length){ brawlerRevealQueue.shift(); sfx('ui'); hide('revealScreen'); showNextReveal(); return; }
  revealQueue.shift(); sfx('ui'); hide('revealScreen'); showNextReveal();
};
// NEW BRAWLER card-flip — reuses the skin suspense reveal, styled as a gold "mythic" card.
function showBrawlerReveal(){
  const key=brawlerRevealQueue[0], c=CHARS[key];
  const scr=document.getElementById('revealScreen');
  drawPortrait(document.getElementById('revealArt'), key, null);
  document.getElementById('revealRarity').textContent='✦ NEW BRAWLER ✦';
  document.getElementById('revealName').textContent=c.name;
  document.getElementById('revealChar').textContent=c.role+(c.blurb?' · '+c.blurb:'');
  const eq=document.getElementById('revealEquip'), lt=document.getElementById('revealLater');
  eq.textContent='PLAY AS '+c.name.toUpperCase(); lt.textContent='LATER';
  ['overScreen','roadScreen','titleScreen','shopScreen','sanctuaryScreen'].forEach(hide);
  scr.className='screen mythic suspense';
  void scr.offsetWidth;
  show('revealScreen');
  sfx('ui');
  clearTimeout(showNextReveal._t);
  showNextReveal._t=setTimeout(()=>{
    if(document.getElementById('revealScreen').classList.contains('hidden')) return;
    scr.className='screen mythic';
    void scr.offsetWidth;
    sfx('unlock');
  }, 1800);
}

/* ---- Skin packs: a roulette that scrolls a pack's portraits and lands on a new one ---- */
let packWinner=null;
// which cosmetics belong to each pack (data-driven, so new packs auto-include their skins)
const PACK_IDS = pack => ALL_COSMETIC_IDS.filter(id=> pack==='playtime' ? COSMETICS[id].pack==='playtime' : pack==='nature' ? COSMETICS[id].pack==='nature' : pack==='space' ? COSMETICS[id].pack==='space' : COSMETICS[id].mythicOnly);
const PACK_LABEL = { mythic_masters:'Mythic Masters', playtime:'Playtime', nature:'Nature', space:'Space' };
function playPackRoulette(packId){
  const packPool = PACK_IDS(packId);
  document.getElementById('packTitle').textContent = packId==='playtime' ? '✦ PLAYTIME ✦' : packId==='nature' ? '✦ NATURE ✦' : packId==='space' ? '✦ SPACE ✦' : '✦ MYTHIC MASTERS ✦';
  // pool for this pack: skins you don't own yet
  const unowned = packPool.filter(id=>!ownsCosmetic(id));
  if(!unowned.length){
    // fully collected — convert the pack to a Pearl payout and move on
    save.pearls+=40; persistSave();
    floatMsgAndContinue();
    return;
  }
  packWinner = unowned[Math.floor(Math.random()*unowned.length)];
  const strip=document.getElementById('packStrip');
  const btns=document.getElementById('packBtns'), res=document.getElementById('packResult'), rc=document.getElementById('packResultChar');
  btns.style.opacity='0'; res.textContent=''; rc.textContent='';
  document.getElementById('packSub').textContent='Opening your skin pack…';
  strip.innerHTML=''; strip.style.transition='none'; strip.style.transform='translateX(0)';
  // build ~34 cells of random mythics; the WINNER sits at a fixed index near the end
  const CELL=132, WINDEX=30, N=WINDEX+4;
  const cells=[];
  for(let i=0;i<N;i++){ cells.push(i===WINDEX ? packWinner : packPool[Math.floor(Math.random()*packPool.length)]); }
  cells.forEach(id=>{ const c=document.createElement('div'); c.className='pcell';
    const cv=document.createElement('canvas'); cv.width=104; cv.height=104; c.appendChild(cv); strip.appendChild(c);
    try{ drawPortrait(cv, COSMETICS[id].char, id); }catch(e){} });
  ['overScreen','roadScreen','titleScreen','shopScreen','sanctuaryScreen','revealScreen'].forEach(hide);
  show('packScreen');
  // center the winner under the marker: reel width center minus half a cell
  const reelW=document.getElementById('packReel').clientWidth;
  const target = -(WINDEX*CELL) + reelW/2 - CELL/2 + 6;
  sfx('unlock');
  // kick the animation next frame so the transition applies
  requestAnimationFrame(()=>{ requestAnimationFrame(()=>{
    strip.style.transition='transform 4.2s cubic-bezier(.12,.7,.12,1)';
    strip.style.transform='translateX('+target+'px)';
  }); });
  setTimeout(()=>{
    const co=COSMETICS[packWinner];
    document.getElementById('packSub').textContent = packId==='playtime' ? 'You pulled a Playtime toy!' : packId==='nature' ? 'You pulled a Nature skin!' : packId==='space' ? 'You pulled a Space skin!' : 'You pulled a Mythic!';
    res.textContent=co.name; rc.textContent='for '+CHARS[co.char].name;
    btns.style.opacity='1'; sfx('unlock');
  }, 4400);
}
// KO-points skin win: the same reel, but with a PRE-DECIDED winner (already granted) + a KO-eligible filler pool.
// Pool = commons + rares of brawlers whose common you already own (no silver, no mythic/special) — matches the KO cycle.
function koReelPool(){
  return ALL_COSMETIC_IDS.filter(id=>{ const c=COSMETICS[id];
    if(c.shopOnly||c.mythicOnly||c.special) return false;          // no silver / mythic / playtime / nature
    if(c.rarity!=='common' && c.rarity!=='rare') return false;
    if(c.rarity==='rare'){ const common=ALL_COSMETIC_IDS.find(s=>COSMETICS[s].char===c.char && COSMETICS[s].rarity==='common'); if(common && !ownsCosmetic(common)) return false; }  // rare needs its common owned
    return true;
  });
}
function playSkinRoulette(winnerId, returnScreen){
  packWinner = winnerId;
  let pool = koReelPool(); if(!pool.length) pool=[winnerId];   // filler cells (visual only)
  const strip=document.getElementById('packStrip');
  const btns=document.getElementById('packBtns'), res=document.getElementById('packResult'), rc=document.getElementById('packResultChar');
  document.getElementById('packTitle').textContent='✦ KO REWARD ✦';
  document.getElementById('packSub').textContent='Rolling your KO skin…';
  btns.style.opacity='0'; res.textContent=''; rc.textContent='';
  strip.innerHTML=''; strip.style.transition='none'; strip.style.transform='translateX(0)';
  const CELL=132, WINDEX=30, N=WINDEX+4;
  for(let i=0;i<N;i++){ const id=(i===WINDEX)?winnerId:pool[Math.floor(Math.random()*pool.length)];
    const c=document.createElement('div'); c.className='pcell';
    const cv=document.createElement('canvas'); cv.width=104; cv.height=104; c.appendChild(cv); strip.appendChild(c);
    try{ drawPortrait(cv, COSMETICS[id].char, id); }catch(e){} }
  ['overScreen','roadScreen','titleScreen','shopScreen','sanctuaryScreen','revealScreen'].forEach(hide);
  show('packScreen');
  const reelW=document.getElementById('packReel').clientWidth;
  const target = -(WINDEX*CELL) + reelW/2 - CELL/2 + 6;
  sfx('unlock');
  requestAnimationFrame(()=>{ requestAnimationFrame(()=>{
    strip.style.transition='transform 4.2s cubic-bezier(.12,.7,.12,1)';
    strip.style.transform='translateX('+target+'px)';
  }); });
  setTimeout(()=>{
    const co=COSMETICS[winnerId];
    document.getElementById('packSub').textContent = co.rarity==='rare' ? 'You rolled a RARE skin!' : 'You rolled a skin!';
    res.textContent=co.name; rc.textContent='for '+CHARS[co.char].name;
    btns.style.opacity='1'; sfx('unlock');
  }, 4400);
}
// used when the pack pool is empty (converted to Pearls): brief note then continue the reward flow
function floatMsgAndContinue(){
  const res=document.getElementById('packResult'), rc=document.getElementById('packResultChar'), btns=document.getElementById('packBtns');
  document.getElementById('packStrip').innerHTML=''; document.getElementById('packSub').textContent='All Mythics collected!';
  res.textContent='+40 🫧 Pearls'; rc.textContent='(pack converted)'; btns.style.opacity='1'; packWinner=null;
  ['overScreen','roadScreen','titleScreen','shopScreen','sanctuaryScreen','revealScreen'].forEach(hide);
  show('packScreen'); sfx('unlock');
}
document.getElementById('packEquip').onclick=()=>{
  if(packWinner){ if(!ownsCosmetic(packWinner)) save.cosmetics.push(packWinner); save.equipped[COSMETICS[packWinner].char]=packWinner; persistSave(); }
  packWinner=null; sfx('ui'); hide('packScreen'); showNextReveal();
};
document.getElementById('packLater').onclick=()=>{
  if(packWinner && !ownsCosmetic(packWinner)){ save.cosmetics.push(packWinner); persistSave(); }   // still granted, just not equipped
  packWinner=null; sfx('ui'); hide('packScreen'); showNextReveal();
};

/* render the Trophy Road */
function renderRoad(){
  document.getElementById('pointsLine').textContent=
    save.points+" to spend  ·  "+save.skinPoints+" KO-points  ·  "+(save.lifetimePoints||0)+" lifetime";
  const track=document.getElementById('roadTrack'); track.innerHTML="";
  const nextId = (nextBrawlerNode()||{}).id;
  TROPHY_ROAD.forEach(n=>{
    const owned = isUnlocked(n.id);
    const next = n.id===nextId;   // the very next brawler you can buy (fixed order)
    const icon = CHARS[n.id]?CHARS[n.id].emoji:'❔';
    const d=document.createElement('div');
    d.className='node'+(owned?' done':'')+(next?' next':'');
    const costLabel = owned?'OWNED':(n.cost===0?'—':n.cost+' trophies');
    d.innerHTML=`<div class="bar"></div><div class="dot">${owned?icon:'🔒'}</div>
      <div class="info"><div class="lab">${n.label}</div>
      <div class="cost">${costLabel}</div></div>`;
    track.appendChild(d);
  });
  // repeating skin node — driven by KO-points, not Trophy Road points
  const moreSkins=availableCosmetics().length>0;
  const cd=document.createElement('div');
  cd.className='node'+(moreSkins?' next':'');
  const loopCost = !moreSkins ? 'all collected'
    : `${save.skinPoints}/${skinCost()} KO-pts`;
  cd.innerHTML=`<div class="bar"></div><div class="dot">🎨</div>
    <div class="info"><div class="lab">Random Skin (KO-pts)</div>
    <div class="cost">${loopCost}</div></div>`;
  track.appendChild(cd);
}

/* cosmetics locker: show owned skins per character, click to equip/unequip */
function renderQuests(){
  ensureQuests();
  const dl=document.getElementById('doublerLine');
  const d=save.doublers||{};
  const bits=[];
  if(d.trophy>0) bits.push(`🏆 Trophy Doubler ×${d.trophy} (next match)`);
  if(d.ko>0) bits.push(`💠 KO-point Doubler ×${d.ko} (next match)`);
  dl.textContent = bits.length ? bits.join("   ·   ") : "No active doublers — complete quests to earn them.";
  // mega-quest counter: progress toward the next MEGA-QUEST (every 10 completed quests)
  const megaActive = save.quests.some(s=>QUEST_BY_ID[s.id] && QUEST_BY_ID[s.id].mega);
  const done = save.questsDone||0, into = done%10, left = 10-into;
  const mct=document.getElementById('megaCounterText'), mcb=document.getElementById('megaCounterBar');
  if(mct && mcb){
    if(megaActive){ mct.textContent='MEGA-QUEST active — finish it below!'; mcb.style.width='100%'; }
    else { mct.textContent=`MEGA-QUEST in ${left} quest${left===1?'':'s'}`; mcb.style.width=`${Math.round(into/10*100)}%`; }
  }
  const list=document.getElementById('questList'); if(!list) return;
  list.innerHTML='';
  // mega-quest (if active) always renders first
  const ordered=save.quests.slice().sort((a,b)=>{ const ma=QUEST_BY_ID[a.id]&&QUEST_BY_ID[a.id].mega?1:0, mb=QUEST_BY_ID[b.id]&&QUEST_BY_ID[b.id].mega?1:0; return mb-ma; });
  ordered.forEach(slot=>{
    const q=QUEST_BY_ID[slot.id]; if(!q) return;
    const frac=clamp(slot.prog/q.goal,0,1);
    const rp=[];
    if(q.reward.tokens) rp.push(`🎟${q.reward.tokens}`);
    if(q.reward.pearls) rp.push(`🫧${q.reward.pearls}`);
    if(q.reward.doubler==='trophy') rp.push('🏆 Doubler');
    if(q.reward.doubler==='ko') rp.push('💠 Doubler');
    if(q.reward.chance) rp.push('+chance');
    if(q.reward.pack) rp.push('✦ Skin Pack');
    const rew = rp.join(' ');
    const ico = q.mega?'✦': q.diff==='hard'?'🔥': q.diff==='med'?'⭐':'🍀';
    const row=document.createElement('div');
    row.className='questRow '+(q.mega?'qmega':q.diff==='hard'?'qhard':q.diff==='med'?'qmed':'qeasy');
    row.innerHTML=`<div class="qico">${ico}</div>
      <div class="qmid"><div class="qtext">${q.text}</div>
        <div class="qbar"><i style="width:${Math.round(frac*100)}%"></i></div>
        <div class="qprog">${slot.prog} / ${q.goal}</div></div>
      <div class="qrew">${rew}</div>`;
    list.appendChild(row);
  });
}
function renderCodex(){
  const grid=document.getElementById('codexGrid'); if(!grid) return;
  grid.innerHTML='';
  Object.entries(CHARS).forEach(([key,c])=>{
    if(key==='dummy' || key==='spore') return;   // training dummy + Binas spore-minion are not collectible brawlers
    const owned=isUnlocked(key);
    const gp=growthProgress(key);
    const tierIdx=GROWTH_TIERS.indexOf(gp.tier);
    const lore=GROWTH_LORE[key]||[];
    const card=document.createElement('div');
    card.className='cxCard'+(owned?'':' cxLocked');
    // progress line toward next tier
    const prog = gp.next
      ? `<div class="cxProg"><div class="cxProgBar"><i style="width:${Math.round(gp.frac*100)}%; background:${gp.next.color}"></i></div>
           <span>${Math.floor(gp.cur)}/${gp.need} → ${gp.next.icon} ${gp.next.name}</span></div>`
      : `<div class="cxProg" style="color:${gp.tier.color}; opacity:.85;">Fully grown — ${gp.tier.icon} ${gp.tier.name}</div>`;
    // lore: fragment i is unlocked when tierIdx >= i (Seedling reveals fragment 0)
    let loreHtml='';
    lore.forEach((frag,i)=>{
      const unlocked = tierIdx>=i;
      const tierFor = GROWTH_TIERS[i];
      loreHtml += unlocked
        ? `<div class="cxLore"><span class="cxLoreIco">${tierFor.icon}</span>${frag}</div>`
        : `<div class="cxLore locked"><span class="cxLoreIco">🔒</span><i>Reach ${tierFor.icon} ${tierFor.name} to reveal…</i></div>`;
    });
    card.innerHTML=`
      <div class="cxHead">
        <canvas width="56" height="56"></canvas>
        <div><div class="cxName">${owned?c.name:'???'}</div><div class="cxRole">${c.emoji} ${c.role}</div></div>
        ${owned?`<div class="cxTier" style="color:${gp.tier.color};">${gp.tier.icon} ${gp.tier.name}</div>`:`<div class="cxTier" style="opacity:.7;">🔒 Locked</div>`}
      </div>
      ${owned?`
      ${prog}
      <div class="cxLoreWrap">${loreHtml}</div>`
      :`<div class="cxBlurb" style="opacity:.6;">Unlock on the Trophy Road to reveal this brawler and their story.</div>`}`;
    grid.appendChild(card);
    if(owned){ try{ drawPortrait(card.querySelector('canvas'),key); }catch(err){} }
  });
}
// a short human-readable move description when a char has no explicit .desc
function moveDesc(m){
  const bits=[];
  if(m.dmg) bits.push(`${m.dmg} dmg`);
  if(m.range) bits.push(`range ${m.range}`);
  if(m.cd) bits.push(`${(m.cd/60).toFixed(1)}s cooldown`);
  return bits.join(' · ')||'—';
}
