// draw Maria Miami: a glamorous siren — flowing coral-pink hair, pearl tiara, seashell top, teal tail, lures with song
function drawSiren(){
  const cv2=document.getElementById('sirenArt'); if(!cv2) return;
  const g=cv2.getContext('2d'); const R=44; g.clearRect(0,0,120,120);
  g.save(); g.translate(60,58);
  const skin="#e6c2a0", hair="#ff6f9c", hairDk="#d94b7c", tail="#2ea8c4", tailLt="#8ff0e8", pearl="#f6f2ea", shell="#ffb3c7";
  // flowing hair BEHIND everything (big, wavy)
  g.fillStyle=hairDk; g.beginPath(); g.ellipse(0,-R*0.35,R*0.78,R*0.9,0,0,6.28); g.fill();
  // shimmering tail (curved S, below)
  g.fillStyle=tail; g.beginPath();
  g.moveTo(-R*0.26,R*0.22); g.quadraticCurveTo(-R*0.05,R*0.85,-R*0.55,R*1.18);
  g.quadraticCurveTo(0,R*1.02,R*0.55,R*1.18); g.quadraticCurveTo(R*0.05,R*0.85,R*0.26,R*0.22); g.closePath(); g.fill();
  // tail fin shimmer + scales
  g.fillStyle=tailLt; g.globalAlpha=0.55; g.beginPath(); g.moveTo(-R*0.55,R*1.18); g.quadraticCurveTo(0,R*0.96,R*0.55,R*1.18); g.quadraticCurveTo(0,R*1.3,-R*0.55,R*1.18); g.fill(); g.globalAlpha=1;
  g.fillStyle=shade(tail,28); for(let k=0;k<7;k++){ g.beginPath(); g.arc(Math.sin(k*1.3)*R*0.16, R*(0.32+k*0.11), 2.6, 0,6.28); g.fill(); }
  // torso
  g.fillStyle=skin; g.beginPath(); g.roundRect(-R*0.22,-R*0.08,R*0.44,R*0.4,R*0.18); g.fill();
  // seashell bikini top
  g.fillStyle=shell; g.strokeStyle=shade(shell,-25); g.lineWidth=1.5;
  g.beginPath(); g.arc(-R*0.11,R*0.04,R*0.13,0,6.28); g.fill(); g.stroke();
  g.beginPath(); g.arc(R*0.11,R*0.04,R*0.13,0,6.28); g.fill(); g.stroke();
  g.strokeStyle=shade(shell,-25); for(let k=-1;k<=1;k++){ g.beginPath(); g.moveTo(-R*0.11,R*0.04); g.lineTo(-R*0.11+Math.cos(1.3+k*0.4)*R*0.13, R*0.04+Math.sin(1.3+k*0.4)*R*0.13); g.moveTo(R*0.11,R*0.04); g.lineTo(R*0.11+Math.cos(1.3+k*0.4)*R*0.13, R*0.04+Math.sin(1.3+k*0.4)*R*0.13); g.stroke(); }
  // one arm resting coyly
  g.fillStyle=skin; g.beginPath(); g.roundRect(R*0.18,-R*0.02,R*0.16,R*0.32,7); g.fill();
  // head
  g.fillStyle=skin; g.beginPath(); g.arc(0,-R*0.42,R*0.32,0,6.28); g.fill();
  // hair framing the face (coral pink, swept to one side)
  g.fillStyle=hair; g.beginPath(); g.arc(0,-R*0.54,R*0.38,Math.PI*0.88,Math.PI*2.12); g.fill();
  g.beginPath(); g.ellipse(-R*0.38,-R*0.28,R*0.16,R*0.55,0.35,0,6.28); g.fill();
  g.beginPath(); g.ellipse(R*0.4,-R*0.3,R*0.18,R*0.6,-0.3,0,6.28); g.fill();
  // lidded, flirty eyes with lashes
  g.strokeStyle="#0a3a3a"; g.lineWidth=2; g.lineCap="round";
  g.beginPath(); g.moveTo(-R*0.17,-R*0.44); g.quadraticCurveTo(-R*0.11,-R*0.4,-R*0.05,-R*0.44); g.stroke();
  g.beginPath(); g.moveTo(R*0.05,-R*0.44); g.quadraticCurveTo(R*0.11,-R*0.4,R*0.17,-R*0.44); g.stroke();
  g.fillStyle="#0a3a3a"; g.beginPath(); g.arc(-R*0.1,-R*0.42,R*0.03,0,6.28); g.arc(R*0.1,-R*0.42,R*0.03,0,6.28); g.fill();
  // lashes
  g.strokeStyle="#0a3a3a"; g.lineWidth=1.2; g.beginPath(); g.moveTo(-R*0.18,-R*0.45); g.lineTo(-R*0.22,-R*0.48); g.moveTo(R*0.18,-R*0.45); g.lineTo(R*0.22,-R*0.48); g.stroke();
  // red lips (sultry smile)
  g.fillStyle="#e0455f"; g.beginPath(); g.ellipse(0,-R*0.3,R*0.08,R*0.045,0,0,6.28); g.fill();
  // pearl tiara
  g.fillStyle=pearl; for(let k=-2;k<=2;k++){ g.beginPath(); g.arc(k*R*0.12,-R*0.68-Math.abs(k)*R*0.015,R*0.05,0,6.28); g.fill(); }
  g.fillStyle="#ffd98a"; g.beginPath(); g.arc(0,-R*0.72,R*0.055,0,6.28); g.fill();
  // ♪ luring song notes floating beside her
  g.fillStyle="#aef0ff"; g.font="bold 15px Trebuchet MS";
  g.globalAlpha=0.5+0.5*Math.abs(Math.sin(frame*0.06));   g.fillText("♪", R*0.95, -R*0.5);
  g.globalAlpha=0.5+0.5*Math.abs(Math.sin(frame*0.06+2)); g.fillText("♫", R*1.1, -R*0.85);
  g.globalAlpha=1;
  g.restore();
}
