  // pointed wizard-astronomer hat
  g.fillStyle=robeDk; g.beginPath(); g.moveTo(-R*0.3,-R*0.34); g.lineTo(0,-R*1.05); g.lineTo(R*0.3,-R*0.34); g.closePath(); g.fill();
