  g.fillStyle=leafLt; g.beginPath(); g.arc(-R*0.24,-R*0.12,R*0.05,0,6.28); g.arc(R*0.26,-R*0.12,R*0.05,0,6.28); g.arc(R*0.02,-R*0.22,R*0.05,0,6.28); g.fill();
  // hood shadow + face (two glowing eyes)
