function drawQuietKid(){
  const cv2=document.getElementById('quietKidArt'); if(!cv2) return;
  const g=cv2.getContext('2d'); const R=44; g.clearRect(0,0,120,120);
  g.save(); g.translate(60,64);
  const hood="#2f3a4a", hoodDk="#1c2530", skin="#e8c19a", eye="#20303c";
  // body / hoodie
  g.fillStyle=hoodDk; g.beginPath(); g.ellipse(0,R*0.7,R*0.82,R*0.6,0,0,6.28); g.fill();
  g.fillStyle=hood; g.beginPath(); g.ellipse(0,R*0.55,R*0.7,R*0.5,0,0,6.28); g.fill();
  // hood over the head
  g.fillStyle=hood; g.beginPath(); g.arc(0,-R*0.28,R*0.62,0,6.28); g.fill();
  // shadowed face inside the hood
  g.fillStyle=skin; g.beginPath(); g.arc(0,-R*0.18,R*0.42,0,6.28); g.fill();
  g.fillStyle="rgba(0,0,0,.35)"; g.beginPath(); g.arc(0,-R*0.32,R*0.5,0.1,Math.PI-0.1); g.fill();   // hood shadow across the brow
  // two shifty eyes glancing to the side
  const look=Math.sin(frame*0.03)*R*0.06;
  g.fillStyle=eye; g.beginPath(); g.arc(-R*0.15+look,-R*0.12,R*0.06,0,6.28); g.arc(R*0.15+look,-R*0.12,R*0.06,0,6.28); g.fill();
  // a sly "🤫" finger-to-lips hint: small hand
  g.fillStyle=skin; g.beginPath(); g.arc(R*0.02,R*0.05,R*0.09,0,6.28); g.fill();
  g.restore();
}
