function renderNature(){
  const al=document.getElementById('acornLine'); if(al) al.textContent=`🌰 ${save.acorns} Acorns`;
  drawForestSpirit(); cycleGroveLore(); if(groveLoreTimer)clearInterval(groveLoreTimer); groveLoreTimer=setInterval(cycleGroveLore,8000);
  refreshNatureEpoch();
  const rc=document.getElementById('natureReset');
  if(rc){ const left=4-(((save.stats&&save.stats.matches)||0)%4); rc.textContent=`🍃 New growth in ${left} match${left>1?'es':''}`; }
  const grid=document.getElementById('natureGrid'); if(!grid) return;
  grid.innerHTML='';
  const skins=(nature.offer||[]);
  if(!skins.length){
    const em=document.createElement('div'); em.className='snEmpty';
    em.textContent="The grove offers nothing new right now — its forms are all in your hands, or the season hasn't turned. Come back next rotation.";
    grid.appendChild(em);
    return;
  }
  skins.forEach(id=>{
    const co=COSMETICS[id], owned=ownsCosmetic(id), canBuy=!owned && save.acorns>=ACORN_PRICE;
    const card=document.createElement('div');
    card.className='snCard snMyth'+(owned?' owned':'');
    card.innerHTML=`<canvas width="60" height="60"></canvas>
      <div>
        <div class="snName">${CHARS[co.char].name}</div>
        <div class="snUp" style="color:#a8e88a;">${co.name}</div>
        <div class="snDesc">Nature form skin</div>
      </div>
      <button class="snBuy${owned?' have':''}" data-nat="${id}" ${owned?'disabled':(canBuy?'':'disabled')}>${owned?'OWNED ✓':'🌰 '+ACORN_PRICE}</button>`;
    grid.appendChild(card);
    { const ib=document.createElement('button'); ib.className='iBtn'; ib.textContent='i'; ib.title='Preview skin';
      ib.onclick=(ev)=>{ ev.stopPropagation(); openSkinPeek(id); }; card.appendChild(ib); }
    try{ drawPortrait(card.querySelector('canvas'), co.char, id); }catch(err){}
  });
  grid.querySelectorAll('.snBuy[data-nat]').forEach(b=>{
    b.onclick=()=>{
      const id=b.dataset.nat, co=COSMETICS[id];
      if(!co || ownsCosmetic(id) || save.acorns<ACORN_PRICE) return;
      save.acorns-=ACORN_PRICE; save.cosmetics.push(id);
      if(!save.equipped[co.char]) save.equipped[co.char]=id;
      persistSave(); sfx('unlock');
      hide('natureScreen'); queueReveals([id], 'natureScreen');
    };
  });
}
// ---- Observatory vendor: The Astronomer (a hooded stargazer) + lore ----
function renderStats(){
  const s=save.stats||{matches:0,wins:0,kos:0,deaths:0,byChar:{}};
  const wr = s.matches? Math.round(s.wins/s.matches*100):0;
  let favKey=null, favN=-1;
  Object.entries(s.byChar||{}).forEach(([k,v])=>{ if(v.matches>favN){favN=v.matches; favKey=k;} });
  const favName = favKey? CHARS[favKey].name : '—';
  const tiles=document.getElementById('statsTiles');
  tiles.innerHTML=`
    <div class="stTile"><div class="stNum">${s.matches}</div><div class="stLbl">MATCHES</div></div>
    <div class="stTile"><div class="stNum">${s.wins}</div><div class="stLbl">WINS</div></div>
    <div class="stTile"><div class="stNum">${wr}%</div><div class="stLbl">WIN RATE</div></div>
    <div class="stTile"><div class="stNum">${s.kos}</div><div class="stLbl">TOTAL KOs</div></div>
    <div class="stTile"><div class="stNum" style="font-size:18px;">${favName}</div><div class="stLbl">FAVOURITE</div></div>`;
  // per-brawler breakdown, most-played first
  const box=document.getElementById('statsChar');
  const rows=Object.entries(s.byChar||{}).sort((a,b)=>b[1].matches-a[1].matches);
  if(rows.length===0){ box.innerHTML=`<div style="opacity:.7; font-size:13px; text-align:center;">Play a match to start tracking your stats.</div>`; return; }
  box.innerHTML='';
  rows.forEach(([k,v])=>{
    if(!CHARS[k]) return;
    const wrK = v.matches? Math.round(v.wins/v.matches*100):0;
    const row=document.createElement('div'); row.className='stRow';
    row.innerHTML=`<canvas width="40" height="40"></canvas>
      <div><div class="srName">${CHARS[k].name}</div><div class="srMeta">${v.matches} matches · ${v.kos} KOs</div></div>
      <div class="srWr"><b>${wrK}%</b><br><span style="opacity:.7;">${v.wins}W</span></div>`;
    box.appendChild(row);
    try{ drawPortrait(row.querySelector('canvas'),k); }catch(err){}
  });
}
function renderCosmetics(){
  const panel=document.getElementById('cosmeticsPanel'); if(!panel) return;  if(save.cosmetics.length===0 && save.emotes.length===0){
    panel.innerHTML=`<div style="opacity:.7; font-size:13px;">Earn ${SKIN_PTS_PER_KO} KO-points per knockout. Every ${SKIN_STEP_PRE} (or ${SKIN_STEP_FULL} once all brawlers are unlocked) earns a random skin. Emotes &amp; Silverdome skins live in the 🎪 Shop.</div>`;
    return;
  }
  let html='';
  if(save.cosmetics.length){
    html+=`<div style="font-size:13px; letter-spacing:2px; opacity:.7; margin-bottom:8px;">YOUR SKINS — click to equip</div><div style="display:flex; gap:8px; flex-wrap:wrap; justify-content:center;">`;
    // group by brawler, then ascending by rarity (Common - Rare/Silver - Special)
    const sorted = save.cosmetics.slice().filter(id=>COSMETICS[id]).sort((a,b)=>{
      const ca=CHARS[COSMETICS[a].char].name, cb=CHARS[COSMETICS[b].char].name;
      if(ca!==cb) return ca<cb?-1:1;
      return rarityRank(a)-rarityRank(b);
    });
    sorted.forEach(id=>{
      const co=COSMETICS[id]; const equipped=save.equipped[co.char]===id;
      const star = rarityStar(co.rarity);
      html+=`<button class="skinChip${equipped?' on':''}" data-id="${id}" style="--sc:${co.color}" title="${co.rarity}">
        <span class="sw" style="box-shadow:0 0 0 2px ${RARITY_COLOR[co.rarity]||'#8fd3a8'}"></span>${CHARS[co.char].emoji} ${star}${co.name}</button>`;
    });
    html+=`</div>`;
  }
  if(save.emotes.length){
    html+=`<div style="font-size:13px; letter-spacing:2px; opacity:.7; margin:14px 0 8px;">YOUR EMOTES — press 💬 in-game to use</div><div style="display:flex; gap:8px; flex-wrap:wrap; justify-content:center;">`;
    save.emotes.forEach(id=>{
      const em=EMOTES[id];
      html+=`<span class="skinChip" style="--sc:#2e6fb0; cursor:default;" title="${CHARS[em.char].name}">${CHARS[em.char].emoji} “${em.text}”</span>`;
    });
    html+=`</div>`;
  }
  panel.innerHTML=html;
  panel.querySelectorAll('.skinChip[data-id]').forEach(btn=>{
    btn.onclick=()=>{
      const id=btn.dataset.id, ch=COSMETICS[id].char;
      save.equipped[ch] = (save.equipped[ch]===id) ? null : id;  // toggle
      persistSave(); sfx('ui'); renderCosmetics();
    };
  });
}


/* ---------- The Silverdome Shop & the "Random Kid" ---------- */
// passive lore the shopkeeper mutters — casino / russian roulette flavor
const KID_LORE = [
  "Random Kid: \"Tokens? Yeah, I run the roulette out back. Six chambers, one's usually... spicy.\"",
  "Random Kid: \"Nobody knows my name. I just show up when there's tokens to spend.\"",
  "Random Kid: \"Word of advice — never load all six. That's not a game, that's a goodbye.\"",
  "Random Kid: \"House always wins? Nah. The house just... doesn't lose as often.\"",
  "Random Kid: \"I traded a skin for a spin once. Kid never came back for it. Weird.\"",
  "Random Kid: \"You spin, you win, or you click. Simple rules in the Silverdome.\"",
  "Random Kid: \"These emotes? Won 'em all at the table. Every single one.\"",
  "Random Kid: \"Careful with five loaded. The payout's fat because the odds ain't.\""
];
let kidLoreTimer=null;
function cycleKidLore(){
  const b=document.getElementById('shopBubble'); if(!b) return;
  b.textContent = KID_LORE[Math.floor(Math.random()*KID_LORE.length)];
}
// draw the mysterious kid: hooded figure, coin, sly grin (deliberately generic — "random kid")
function drawShopKid(){
  const cv2=document.getElementById('shopKidArt'); if(!cv2) return;
  const g=cv2.getContext('2d'); const R=44; g.clearRect(0,0,120,120);
  g.save(); g.translate(60,64);
  const hood="#3a4150", hoodDk="#262c38", skin="#e8c19a", coin="#e8b64a";
  // body/cloak
  g.fillStyle=hood; g.beginPath();
  g.moveTo(-R*0.7,R*0.9); g.quadraticCurveTo(-R*0.9,-R*0.2,-R*0.35,-R*0.5);
  g.lineTo(R*0.35,-R*0.5); g.quadraticCurveTo(R*0.9,-R*0.2,R*0.7,R*0.9); g.closePath(); g.fill();
  // face in shadow under the hood
  g.fillStyle=skin; g.beginPath(); g.arc(0,-R*0.4,R*0.34,0,6.28); g.fill();
  g.fillStyle=hoodDk; g.beginPath(); g.arc(0,-R*0.62,R*0.5,Math.PI*0.95,Math.PI*2.05); g.fill(); // hood brim shadow
  // sly eyes
  g.fillStyle="#20242e"; g.beginPath(); g.arc(-R*0.12,-R*0.38,R*0.05,0,6.28); g.arc(R*0.12,-R*0.38,R*0.05,0,6.28); g.fill();
  g.strokeStyle="#8a5a3a"; g.lineWidth=2; g.beginPath(); g.arc(0,-R*0.28,R*0.12,0.2,Math.PI-0.2); g.stroke();
  // flipping coin
  g.fillStyle=coin; g.beginPath(); g.ellipse(R*0.55,-R*0.1,R*0.1,R*0.16,0.3,0,6.28); g.fill();
  g.fillStyle=shade(coin,-30); g.beginPath(); g.arc(R*0.55,-R*0.1,R*0.05,0,6.28); g.fill();
  g.restore();
}
function openShop(returnScreen){
  ['titleScreen','overScreen','roadScreen','selectScreen','optionsScreen'].forEach(hide);
  document.getElementById('shopScreen').dataset.return = returnScreen||'titleScreen';
  show('shopScreen');
  drawShopKid(); cycleKidLore();
  if(kidLoreTimer) clearInterval(kidLoreTimer);
  kidLoreTimer=setInterval(cycleKidLore, 8000);   // passive lore bubbles
  document.getElementById('casinoResult').textContent="";
  refreshShopEpoch();   // rotate the trio only when a new 5-win window has been reached
  renderShop();
}
function closeShop(){
  if(kidLoreTimer){ clearInterval(kidLoreTimer); kidLoreTimer=null; }
  const ret=document.getElementById('shopScreen').dataset.return||'titleScreen';
  hide('shopScreen'); show(ret);
  if(ret==='marketScreen') renderMarket();
}
// small seeded RNG so a given 5-win "epoch" always shows the same trio
function seededRand(seed){ let s=seed*2654435761 % 2147483647; return ()=>{ s=(s*48271)%2147483647; return s/2147483647; }; }
// the shop's stock rotates every 5 rounds won (an "epoch"); slots refill individually after a buy
function buildOffersForEpoch(epoch){
  const pool=[];
  ALL_COSMETIC_IDS.filter(id=>COSMETICS[id].shopOnly && !ownsCosmetic(id)).forEach(id=>pool.push({kind:'skin',id}));
  ALL_EMOTE_IDS.filter(id=>!ownsEmote(id) && !EMOTES[id].skinLocked).forEach(id=>pool.push({kind:'emote',id}));
  const rnd=seededRand(epoch+1);
  for(let i=pool.length-1;i>0;i--){ const j=Math.floor(rnd()*(i+1)); [pool[i],pool[j]]=[pool[j],pool[i]]; }
  // slots: an entry can be null while it's "refilling" after a purchase
  return pool.slice(0,3).map(o=>({...o, refilling:false}));
}
// pick one replacement item not already offered/owned (for a slot refill)
function pickReplacement(){
  const taken=new Set((arena.shopOffer||[]).filter(Boolean).map(o=>o.id));
  const pool=[];
  ALL_COSMETIC_IDS.filter(id=>COSMETICS[id].shopOnly && !ownsCosmetic(id) && !taken.has(id)).forEach(id=>pool.push({kind:'skin',id}));
  ALL_EMOTE_IDS.filter(id=>!ownsEmote(id) && !EMOTES[id].skinLocked && !taken.has(id)).forEach(id=>pool.push({kind:'emote',id}));
  if(!pool.length) return null;
  return pool[Math.floor(Math.random()*pool.length)];
}
// regenerate the trio if we've crossed into a new 5-win epoch since it was last built
function refreshShopEpoch(){
  const epoch=Math.floor((save.totalArenaWins||0)/5);
  if(arena.shopEpoch!==epoch || !arena.shopOffer){
    arena.shopEpoch=epoch;
    arena.shopOffer=buildOffersForEpoch(epoch);
  }
}
function renderShop(){
  document.getElementById('tokenLine').textContent=`🎟 ${save.tokens} Silver Tokens`;
  const untilRotate = 5 - ((save.totalArenaWins||0) % 5);
  const rf=document.getElementById('shopRefresh');
  if(rf) rf.textContent = `the stall restocks in ${untilRotate} more win${untilRotate===1?'':'s'}`;
  const wrap=document.getElementById('shopOffers'); if(!wrap) return;
  refreshShopEpoch();
  wrap.innerHTML='';
  const anyLeft = arena.shopOffer.some(o=>o);
  if(!anyLeft){
    wrap.innerHTML=`<div style="opacity:.7; font-size:13px; padding:20px;">Random Kid: "You've cleaned me out, champ. Nothing left but the roulette."</div>`;
    return;
  }
  arena.shopOffer.forEach((off, slot)=>{
    if(!off){   // an empty slot that's refilling
      const ph=document.createElement('div'); ph.className='shopCard owned';
      ph.innerHTML=`<div class="stype">restocking…</div><div class="sname" style="opacity:.6;">🕓</div><div class="scost" style="opacity:.6;">new item soon</div>`;
      wrap.appendChild(ph); return;
    }
    const isSkin = off.kind==='skin';
    const meta = isSkin ? COSMETICS[off.id] : EMOTES[off.id];
    const cost = isSkin ? SILVER_SKIN_COST : EMOTE_COST;
    const owned = isSkin ? ownsCosmetic(off.id) : ownsEmote(off.id);
    const card=document.createElement('div');
    card.className='shopCard'+(owned?' owned':'');
    const cv2=document.createElement('canvas'); cv2.width=76; cv2.height=76;
    const label = isSkin ? meta.name : `“${meta.text}”`;
    card.innerHTML=`<div class="stype">${isSkin?'❖ Silverdome Skin':'💬 Emote'}</div>`;
    card.appendChild(cv2);
    card.insertAdjacentHTML('beforeend',
      `<div class="sname">${CHARS[meta.char].emoji} ${label}</div>
       <div class="scost">${owned?'OWNED ✓':`🎟 ${cost}`}</div>`);
    if(isSkin) card.insertAdjacentHTML('afterbegin',`<div class="ribbon">RARE</div>`);
    if(isSkin){ const ib=document.createElement('button'); ib.className='iBtn'; ib.textContent='i'; ib.title='Preview skin';
      ib.onclick=(ev)=>{ ev.stopPropagation(); openSkinPeek(off.id); }; card.appendChild(ib); }
    wrap.appendChild(card);
    // portrait: skins draw the brawler in that skin; emotes just draw the brawler
    try{ drawPortrait(cv2, meta.char, isSkin?off.id:null); }catch(e){}
    if(!owned){
      card.onclick=()=>{
        if(save.tokens<cost){ document.getElementById('shopBubble').textContent="Random Kid: \"Not enough tokens, pal. Win some rounds.\""; sfx('ui'); return; }
        save.tokens-=cost;
        if(isSkin){ save.cosmetics.push(off.id); if(!save.equipped[meta.char]) save.equipped[meta.char]=off.id; }
        else { save.emotes.push(off.id); }
        persistSave(); sfx('unlock');
        document.getElementById('shopBubble').textContent="Random Kid: \"Pleasure doing business. Give it a sec, I'll dig out another.\"";
        arena.shopOffer[slot]=null;    // empty the slot; refill after 5s
        renderShop();
        // skins get the full celebratory reveal (returns to the shop after); emotes just confirm
        if(isSkin){ hide('shopScreen'); queueReveals([off.id], 'shopScreen'); }
        setTimeout(()=>{
          // only refill if the shop is still open and the slot is still empty
          if(document.getElementById('shopScreen').classList.contains('hidden')) return;
          if(arena.shopOffer[slot]) return;
          const rep=pickReplacement();
          arena.shopOffer[slot]= rep ? {...rep, refilling:false} : undefined;
          renderShop();
        }, 5000);
      };
    }
  });
}
// --- casino: instalable russian roulette ---
const ROULETTE_MULT = {1:1.2, 2:1.5, 3:2, 4:3, 5:6};   // loaded chambers -> payout multiplier
function spinRoulette(){
  const bet=Math.max(1, Math.floor(+document.getElementById('betInput').value||1));
  const loaded=Math.min(5, Math.max(1, +document.getElementById('chambersInput').value||1));
  const res=document.getElementById('casinoResult');
  if(save.tokens<bet){ res.style.color="#e04b3a"; res.textContent="Not enough tokens to bet that."; sfx('ui'); return; }
  save.tokens-=bet;   // ante up
  const hit = Math.random() < (loaded/6);   // landed on a loaded chamber?
  if(hit){
    res.style.color="#e04b3a"; res.textContent=`🔴 BANG! The chamber was loaded — you lost ${bet} token${bet>1?'s':''}.`;
    sfx('super'); document.getElementById('shopBubble').textContent="Random Kid: \"Oof. Told ya. The house doesn't lose often.\"";
  } else {
    const win=Math.round(bet*ROULETTE_MULT[loaded]);
    save.tokens+=win;
    res.style.color="#8fd3a8"; res.textContent=`⚪ *click* — you survived! Won ${win} token${win>1?'s':''} (×${ROULETTE_MULT[loaded]}).`;
    sfx('unlock'); document.getElementById('shopBubble').textContent="Random Kid: \"Lucky. Or good. Hard to tell in here.\"";
  }
  persistSave(); renderShop();
}


/* ---------- Main loop (fixed timestep: sim always runs at 60Hz regardless of render FPS) ---------- */
loadSave();
updateTouchUI();   // apply phone layout immediately if on a touch device
syncBgScene();     // show the painted scene behind the title on load
refreshModeLocks();   // paint mode-card strips + apply unlock visibility on first paint
// First run (or once after a tutorial-version bump): auto-launch the interactive tutorial once.
if((save.tutorialSeen||0) < TUTORIAL_VERSION){ setTimeout(()=>{ if(state==="title") launchTutorial(); }, 350); }
let _lastT=performance.now(), _acc=0;
const STEP=1000/60;           // ms per logical tick
function loop(now){
  try{
    let dt=now-_lastT; _lastT=now;
    if(dt>250) dt=250;        // clamp after a tab stall so we don't spiral
    _acc+=dt;
    let steps=0;
    while(_acc>=STEP && steps<5){   // catch up, but cap steps/frame to stay responsive
      _acc-=STEP; steps++;
      if(state==="play"){
        if(hitStop>0){ hitStop--; }
        else update();
      }
      if(shake>0.2) shake*=0.78; else shake=0;
    }
    if(steps===0 && _acc>STEP*4) _acc=0;  // safety: never let the accumulator run away
    draw();
  }
  catch(err){ console.error("frame error:",err); if(!window._frameErrShown){ window._frameErrShown=true; throw err; } }
  raf=requestAnimationFrame(loop);
}
requestAnimationFrame(loop);
